CARDIO.register({"item":"230","meta":{"num":230,"short":"Douleur thoracique","title":"Douleur thoracique aiguë","section":"I","chapter":6,"pages":"151-163","sdd":[{"num":161,"label":"Douleur thoracique"},{"num":162,"label":"Dyspnée"},{"num":178,"label":"Demande/prescription raisonnée et choix d'un examen diagnostique"},{"num":185,"label":"Réalisation et interprétation d'un électrocardiogramme (ECG)"},{"num":203,"label":"Élévation de la protéine C-réactive (CRP)"},{"num":204,"label":"Élévation des enzymes cardiaques"},{"num":259,"label":"Évaluation et prise en charge de la douleur aiguë"}]},"objectives":[{"id":"230-obj-01","rank":"A","rubric":"Définition","title":"Savoir définir une douleur thoracique aiguë","desc":""},{"id":"230-obj-02","rank":"A","rubric":"Identifier une urgence","title":"Savoir rechercher une détresse vitale devant une douleur thoracique","desc":"Détresse respiratoire ou hémodynamique, troubles de la conscience"},{"id":"230-obj-03","rank":"A","rubric":"Identifier une urgence","title":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","desc":""},{"id":"230-obj-04","rank":"A","rubric":"Diagnostic positif","title":"Savoir évoquer les 4 urgences cardiovasculaires devant une douleur thoracique","desc":"Dissection aortique, syndromes coronariens aigus, péricardite avec tamponnade, embolie pulmonaire"},{"id":"230-obj-05","rank":"A","rubric":"Diagnostic positif","title":"Connaître la sémiologie clinique fonctionnelle et physique de la dissection aortique","desc":""},{"id":"230-obj-06","rank":"A","rubric":"Diagnostic positif","title":"Connaître la démarche diagnostique des 4 urgences cardiovasculaires","desc":"Terrain évocateur, caractéristiques de la douleur thoracique, particularités de l'examen clinique"},{"id":"230-obj-07","rank":"A","rubric":"Examens complémentaires","title":"Connaître les anomalies électrocardiographiques des 4 urgences cardiovasculaires","desc":""},{"id":"230-obj-08","rank":"A","rubric":"Examens complémentaires","title":"Connaître la place et les anomalies de la radiographie thoracique des 4 urgences cardiovasculaires","desc":""},{"id":"230-obj-09","rank":"A","rubric":"Examens complémentaires","title":"Connaître les examens biologiques à prescrire et leur interprétation des 4 urgences cardiovasculaires","desc":""},{"id":"230-obj-10","rank":"B","rubric":"Examens complémentaires","title":"Connaître la place de la coronarographie dans le diagnostic et les principes de prise en charge du syndrome coronarien aigu","desc":""},{"id":"230-obj-11","rank":"B","rubric":"Examens complémentaires","title":"Connaître la place de l'échocardiographie, de l'ETO et du scanner thoracique dans le diagnostic de dissection aortique","desc":""},{"id":"230-obj-12","rank":"B","rubric":"Étiologies","title":"Devant un angor d'effort, connaître les principales causes d'angor fonctionnel","desc":"Rétrécissement aortique serré, cardiomyopathie hypertrophique, tachycardies (fibrillation atriale), anémie, hyperthyroïdie"},{"id":"230-obj-13","rank":"A","rubric":"Étiologies","title":"Connaître les principales causes thoraciques de douleur aiguë en dehors des 4 urgences cardiovasculaires","desc":"Pneumonie, pneumothorax (cf. items correspondants)"},{"id":"230-obj-14","rank":"A","rubric":"Étiologies","title":"Connaître les principales causes extra-thoraciques de douleur thoracique","desc":"Pancréatite, cholécystite, ulcère, RGO (cf. items correspondants)"}],"course":{"sections":[{"id":"230-sec-01","title":"Douleur thoracique aiguë : cadre général et détresse vitale","rank":"A","objectives":["230-obj-01","230-obj-02","230-obj-03"],"content":"La douleur thoracique aiguë est l'un des motifs de recours aux soins les plus fréquents, aux urgences comme en consultation. Sa prise en charge suit une démarche en deux temps : éliminer d'abord une menace vitale immédiate, puis rechercher les grandes urgences cardiovasculaires.\n\n**Première étape : rechercher une détresse vitale**, indispensable avant toute caractérisation fine de la douleur, car elle impose des mesures thérapeutiques immédiates.\n\n- **Détresse respiratoire** : fréquence anormale (polypnée > 30/min ou bradypnée < 10/min, voire pause respiratoire), mise en jeu des muscles respiratoires accessoires (tirage), sueurs, cyanose, désaturation (SpO2 < 90 %), encéphalopathie respiratoire.\n- **Détresse hémodynamique** : arrêt circulatoire (pouls carotidien/fémoral non perçu, patient inconscient), état de choc (collapsus, hypoperfusion périphérique, pâleur, marbrures, oligurie), signes de cœur pulmonaire, pouls paradoxal.\n- **Atteinte neurologique** : confusion, agitation, convulsions.\n\n> La présence de ces signes prime sur l'analyse sémiologique de la douleur : elle impose une prise en charge en réanimation ou en USIC avant toute démarche diagnostique fine.\n\nUne fois la détresse vitale écartée ou traitée, la seconde étape consiste à rechercher systématiquement l'une des quatre urgences cardiovasculaires. Le transfert d'un patient pour douleur thoracique suspecte doit être **médicalisé, via le 15** : ne pas y recourir devant un tableau évocateur de syndrome coronarien est considéré comme une faute grave, en raison du risque de fibrillation ventriculaire et d'une mortalité préhospitalière élevée.","keyPoints":["La détresse vitale s'évalue avant toute caractérisation fine de la douleur.","Trois types de détresse à rechercher : respiratoire, hémodynamique, neurologique.","Polypnée > 30/min, bradypnée < 10/min et SpO2 < 90 % signent une détresse respiratoire.","Le transfert d'un patient douloureux thoracique suspect doit passer par le 15."],"pitfalls":["Ne pas méconnaître une détresse vitale débutante devant une douleur en apparence banale.","Ne pas recourir au 15 devant un tableau évocateur de SCA est une faute reconnue."],"src":"p. 151-153"},{"id":"230-sec-02","title":"Les quatre urgences cardiovasculaires : repérage et démarche commune","rank":"A","objectives":["230-obj-04","230-obj-06","230-obj-07","230-obj-08","230-obj-09","230-obj-10","230-obj-11"],"content":"Devant toute douleur thoracique aiguë, une fois la détresse vitale écartée, il faut évoquer systématiquement les **quatre urgences cardiovasculaires**, retenues par le moyen mnémotechnique **« PIED »** : Péricardite (avec risque de tamponnade), Infarctus (syndrome coronarien aigu), Embolie pulmonaire, Dissection aortique.\n\nUne cinquième cause, exceptionnelle mais à garder en mémoire, est la **rupture de l'œsophage** : à évoquer devant une douleur thoracique associée à une dyspnée, un emphysème sous-cutané (crépitation neigeuse) ou un pneumomédiastin.\n\n**Examens complémentaires systématiques**, quelle que soit l'orientation clinique :\n- ECG 12 dérivations, complété par V3R, V4R, V7, V8, V9 ;\n- radiographie pulmonaire ;\n- dosage des troponines ultrasensibles.\n\nEn cas de syndrome coronarien aigu avec sus-décalage persistant du segment ST, le patient est transféré **directement vers la coronarographie** (ou en USIC), par transfert médicalisé (appel du 15), en raison du risque de fibrillation ventriculaire.\n\n> [B] La coronarographie occupe une place à la fois diagnostique et thérapeutique de première intention dans le SCA ST+ ; l'échocardiographie (ETT/ETO) et le scanner thoracique occupent une place centrale dans le diagnostic de la dissection aortique, dès lors que l'état hémodynamique le permet.\n\nLe terrain, les caractéristiques de la douleur et les particularités de l'examen clinique orientent ensuite vers l'une de ces quatre urgences (démarche détaillée dans les sections suivantes).","keyPoints":["Mnémotechnique PIED : Péricardite, Infarctus, Embolie pulmonaire, Dissection.","ECG, radiographie pulmonaire et troponine ultrasensible sont systématiques devant toute suspicion.","L'ECG doit inclure les dérivations V3R, V4R, V7, V8, V9.","La rupture de l'œsophage est une 5e urgence rare à ne pas oublier.","Le SCA ST+ impose un transfert direct vers la coronarographie via le 15."],"pitfalls":["Oublier les dérivations postérieures/droites peut faire manquer une ischémie circonflexe ou du VD.","Attendre la troponine avant de traiter un SCA ST+ retarde la reperfusion : erreur grave."],"src":"p. 151-153"},{"id":"230-sec-03","title":"Syndrome coronarien aigu : orientation diagnostique","rank":"A","objectives":["230-obj-06","230-obj-07","230-obj-08","230-obj-09","230-obj-10"],"content":"Le syndrome coronarien aigu (SCA) est évoqué sur un terrain de facteurs de risque cardiovasculaire et/ou d'antécédents coronariens.\n\n**Présentation** : douleur spontanée de repos, angor de novo ou crescendo. L'infarctus est à évoquer dès que la douleur dépasse **20 minutes**. Une dyspnée est associée dans environ **10 %** des cas.\n\n**Douleur typique** : rétrosternale, constrictive ou à type de brûlure/pesanteur, irradiant vers le cou, les épaules, les avant-bras ou la mâchoire, avec sueurs et nausées. Les présentations atypiques sont fréquentes, en particulier chez la femme et le sujet âgé, où la douleur peut siéger de la mandibule à l'ombilic et mimer une atteinte digestive.\n\n**Examen clinique** : normal en dehors de toute complication ; rechercher une autre localisation de l'athérosclérose (souffle carotidien/fémoral, abolition d'un pouls).\n\n**ECG** : à réaliser en urgence, car il conditionne la prise en charge (sus- ou sous-décalage du segment ST, ondes T négatives, ondes Q).\n\n> Un ECG normal en pleine douleur n'élimine pas le diagnostic. Un bloc de branche gauche nouveau doit être considéré comme un équivalent de SCA ST+. Une ischémie circonflexe peut être électriquement muette sur les dérivations standard (penser à V7-V8-V9) ou se traduire par un sous-décalage de V2 à V4, à traiter comme un ST+.\n\n**Radiographie pulmonaire** : normale et souvent inutile dans les formes typiques sans insuffisance cardiaque.\n\n**Troponine ultrasensible** :\n- SCA ST+ confirmé à l'ECG : le dosage est inutile à la décision et **ne doit jamais retarder** la reperfusion (angioplastie ou thrombolyse).\n- SCA sans sus-décalage persistant : intérêt diagnostique et pronostique majeur. Un dosage H0 très faible/faible sans cinétique significative à H1-H2 oriente vers un diagnostic différentiel ou un SCA à bas risque (surveillance en USIC) ; un dosage élevé, ou une augmentation significative à H1-H2, pose le diagnostic de SCA sans ST+ à haut risque.","keyPoints":["Douleur > 20 minutes chez un patient à risque = infarctus jusqu'à preuve du contraire.","L'ECG conditionne la prise en charge et doit être réalisé au plus vite.","Un BBG nouveau vaut équivalent de SCA ST+.","Penser à V7-V8-V9 pour ne pas méconnaître une ischémie circonflexe.","Dans le SCA ST+, la troponine ne doit jamais retarder la reperfusion.","Dans le SCA sans ST+, la cinétique de troponine à 1-2 h oriente diagnostic et risque."],"pitfalls":["Un ECG normal en pleine douleur n'élimine pas un SCA.","Attendre le résultat de la troponine avant de reperfuser un ST+ est une faute.","Méconnaître une présentation atypique chez la femme ou le sujet âgé."],"src":"p. 154-155"},{"id":"230-sec-04","title":"Dissection aortique thoracique","rank":"A","objectives":["230-obj-05","230-obj-06","230-obj-07","230-obj-08","230-obj-09","230-obj-11"],"content":"**Facteurs favorisants** : HTA ancienne, syndrome de Marfan.\n\n**Douleur** : aiguë, prolongée, intense, à type de déchirement, irradiant dans le dos, migratrice et descendant vers les lombes ; parfois associée à une syncope.\n\n**Examen clinique**, selon le siège de la dissection : asymétrie tensionnelle (différence **> 20 mmHg**), abolition d'un pouls, souffle d'insuffisance aortique, déficit neurologique focal.\n\n**Complications révélatrices possibles** : ischémie aiguë de membre, AVC, tableau pseudo-mésentérique avec douleur abdominale trompeuse, hémopéricarde avec tamponnade.\n\n**[B] Score de probabilité clinique** (1 point par catégorie présente, sur 3 au total) :\n\n| Critère | Éléments |\n|---|---|\n| Terrain évocateur | Marfan, ATCD familial de maladie aortique, anévrisme/valvulopathie aortique connus, chirurgie aortique |\n| Douleur évocatrice | thoracique/dorsale/abdominale, brutale, intense, en déchirement |\n| Examen évocateur | abolition de pouls, asymétrie tensionnelle, déficit neuro focal, insuffisance aortique, hypotension/choc |\n\nProbabilité **faible si score 0-1**, **forte si score 2-3**.\n\n**ECG** : normal, ou signes de SCA si la dissection s'étend à une artère coronaire.\n\n**Radiographie thoracique** : élargissement du médiastin, épanchement pleural possible, double contour aortique.\n\n**Biologie** : NFS, plaquettes, CRP, D-dimères, troponine ultrasensible, CPK, créatininémie. Des D-dimères normaux rendent le diagnostic rare.\n\n**Imagerie** : le diagnostic peut être posé par échocardiographie (ETT, ou ETO si stabilité hémodynamique), mais l'**angioscanner thoracique** est souvent nécessaire, notamment pour planifier un geste chirurgical (porte d'entrée, extension, atteintes carotidienne/mésentérique/rénale). Chez un patient stable à faible probabilité clinique, l'échographie est complétée par la radiographie et les D-dimères.\n\n> [B] Prise en charge chirurgicale en urgence si atteinte de l'aorte ascendante (type A de Stanford, types I-II de De Bakey), sauf formes limitées à l'aorte descendante (type B) non compliquées. [A] La pression artérielle doit être normalisée en urgence (urgence hypertensive).","keyPoints":["HTA ancienne et syndrome de Marfan sont les principaux facteurs favorisants.","Douleur migratrice, en déchirement, irradiant vers le dos et les lombes.","Score de probabilité clinique : 3 critères, 1 point chacun ; faible si 0-1, forte si 2-3.","L'angioscanner thoracique est souvent l'examen clé ; l'ETO si l'état hémodynamique le permet.","Type A (aorte ascendante) = chirurgie urgente ; type B non compliqué = traitement médical.","La pression artérielle doit être normalisée en urgence."],"pitfalls":["Un ECG normal n'exclut pas une dissection.","Des D-dimères normaux sont rares mais possibles : ne pas s'y fier isolément si la clinique est très évocatrice.","Ne pas tolérer une HTA au prétexte de perfusion d'organe : elle doit être normalisée."],"src":"p. 155-156"},{"id":"230-sec-05","title":"Embolie pulmonaire","rank":"A","objectives":["230-obj-06","230-obj-07","230-obj-08","230-obj-09"],"content":"**Terrain** : cancer, contraception œstroprogestative associée au tabac, période postopératoire, post-partum, alitement, antécédents personnels/familiaux de maladie thromboembolique.\n\n**Présentation** : douleur basithoracique associée à une dyspnée aiguë, polypnée, toux, parfois hémoptysie tardive. Deux tableaux opposés :\n- **infarctus pulmonaire** : douleur basithoracique pariéto-pleurale, fébrile, hémoptysie noirâtre tardive (bon pronostic) ;\n- **cœur pulmonaire aigu** : dyspnée isolée et signes de défaillance ventriculaire droite ou collapsus, la douleur passant au second plan.\n\n**Examen** : signes de thrombose veineuse (absents dans un tiers des cas), tachycardie, signes d'insuffisance ventriculaire droite (signe de gravité).\n\n**ECG** : tachycardie sinusale, aspect S1Q3, bloc de branche droit, ondes T négatives en précordial droit (V1-V3).\n\n**Radiographie pulmonaire** : souvent normale ; peut montrer atélectasies en bandes, épanchement pleural basal, coupole surélevée, hyperclarté. L'association **douleur + dyspnée + radiographie normale** doit faire évoquer le diagnostic.\n\n**Stratification du risque** : une hypotension (PAS < 90 mmHg ou chute de PAS > 40 mmHg pendant plus de 15 minutes) ou un choc définit un **haut risque**.\n- EP à haut risque : scanner thoracique en urgence si disponible immédiatement, sinon échocardiographie (dilatation du VD).\n- EP sans choc : probabilité clinique estimée par le score de Wells modifié ou de Genève modifié.\n  - Probabilité faible/modérée : dosage des D-dimères. Positifs (**> 500 µg/L**, ou **> 10 × l'âge** après 50 ans, ESC 2019) → angioscanner thoracique. Négatifs (méthode Elisa) → diagnostic éliminé, même en cas de probabilité prétest modérée.\n  - Probabilité forte : D-dimères inutiles, angioscanner d'emblée.\n  - Probabilité intermédiaire ou haute : traitement antithrombotique débuté avant même la confirmation diagnostique.","keyPoints":["Triade évocatrice : douleur + dyspnée + radiographie thoracique normale.","Deux tableaux cliniques opposés : infarctus pulmonaire vs cœur pulmonaire aigu.","ECG : S1Q3, BBD, T négatives en V1-V3, tachycardie sinusale.","Haut risque si PAS < 90 mmHg ou chute > 40 mmHg pendant plus de 15 minutes.","D-dimères positifs si > 500 µg/L ou > 10 × l'âge après 50 ans.","En forte probabilité clinique, pas de D-dimères : angioscanner d'emblée."],"pitfalls":["Une radiographie thoracique normale n'exclut pas l'EP : elle la rend au contraire plus probable dans ce contexte.","Doser les D-dimères en cas de forte probabilité clinique ne change pas la décision.","Attendre la confirmation diagnostique avant de traiter en probabilité intermédiaire/haute est une erreur."],"src":"p. 156-157"},{"id":"230-sec-06","title":"Péricardite aiguë, tamponnade et myopéricardite","rank":"A","objectives":["230-obj-04","230-obj-06","230-obj-07","230-obj-08","230-obj-09"],"content":"**Péricardite aiguë non compliquée**\n- Terrain : contexte viral, fièvre, ou antécédent de péricardite (forme récidivante).\n- Douleur augmentée par l'inspiration profonde et le décubitus, calmée par l'antéflexion du buste.\n- Examen : frottement péricardique, fugace et inconstant.\n- ECG : sus-décalage du segment ST **concave**, diffus ou non systématisé, sans miroir ni onde Q, sous-décalage du segment PQ, microvoltage.\n- Radiographie : parfois élargissement de la silhouette cardiaque.\n- Échocardiographie et troponine systématiques ; syndrome inflammatoire biologique possible. L'échographie peut montrer un épanchement ou être normale (péricardite « sèche ») : il faut savoir la répéter.\n- C'est l'étiologie la plus bénigne des quatre urgences : diagnostic d'élimination.\n\n**Tamponnade péricardique** — urgence vitale, à l'inverse de la forme non compliquée :\n- Douleur avec dyspnée, polypnée puis orthopnée, toux, parfois dysphagie/nausée/hoquet.\n- Signes droits : turgescence jugulaire, reflux hépatojugulaire.\n- Signes de choc : tachycardie, PAS < 90 mmHg.\n- **Pouls paradoxal** : chute de la PAS à l'inspiration **> 10 mmHg** par rapport à l'expiration.\n- ECG : microvoltage, parfois alternance électrique.\n- Radiographie : cardiomégalie, aspect en « carafe » si épanchement abondant.\n- Échocardiographie : confirme le diagnostic (collapsus des cavités droites en expiration, compression du VG par le VD en inspiration, épanchement abondant).\n\n**Myopéricardite** :\n- Péricardite avec atteinte myocardique, le plus souvent virale ; peut mimer un SCA, parfois avec insuffisance cardiaque.\n- Élévation prolongée de la troponine.\n- Échocardiographie : trouble cinétique segmentaire ou diffus du VG, épanchement péricardique possible.\n- Coronarographie normale.\n- IRM : œdème et rehaussement tardif prédominant en sous-épicardique, sans systématisation artérielle — outil clé pour la différencier d'un SCA.","keyPoints":["La péricardite non compliquée est la plus bénigne des 4 urgences, mais reste un diagnostic d'élimination.","Douleur positionnelle : augmentée en décubitus/inspiration, calmée par l'antéflexion.","ECG typique : sus-ST concave diffus sans miroir, sous-décalage de PQ.","La tamponnade est une urgence vitale avec pouls paradoxal et signes droits.","La myopéricardite mime un SCA mais la coronarographie est normale.","L'IRM cardiaque aide à distinguer myopéricardite (rehaussement sous-épicardique) et infarctus."],"pitfalls":["Une échocardiographie normale n'élimine pas une péricardite sèche : il faut savoir la répéter.","Méconnaître les signes de gravité de la tamponnade, urgence vitale contrairement à la péricardite simple.","L'élévation de troponine dans la myopéricardite peut égarer vers un SCA."],"src":"p. 157-158"},{"id":"230-sec-07","title":"Synthèse comparative des quatre urgences cardiovasculaires","rank":"A","objectives":["230-obj-04","230-obj-06","230-obj-07","230-obj-08","230-obj-09"],"content":"Le tableau suivant reprend, pour chacune des quatre urgences cardiovasculaires, les éléments cliniques et paracliniques essentiels à connaître par cœur pour orienter rapidement le diagnostic.\n\n| | SCA | Dissection aortique | Embolie pulmonaire | Péricardite |\n|---|---|---|---|---|\n| Terrain | FDR cardiovasculaire | FDR CV, surtout HTA | Âge, comorbidités, chirurgie récente, néoplasie | Sujet jeune, contage viral |\n| Mode de survenue | Brutal | Brutal | Progressif, avec dyspnée | Aigu |\n| Horaire | Effort ou repos | Repos | Repos | Inspiration, décubitus |\n| Siège/irradiation | Rétrosternale, épigastrique, mâchoire, bras, interscapulaire | Rétrosternale, transfixiante | Latéro- ou basithoracique | Rétrosternale |\n| Type | Constrictif, brûlure | Coup de poignard | — | Constrictif |\n| ECG | Ischémie (sus/sous-ST, ondes T) | Normal ou ischémie si extension coronaire | Tachycardie sinusale, BBD, T négatives, S1Q3 | Sus-ST concave, sous-PQ |\n| Troponine | Utile seulement si non ST+ | ± | + (valeur pronostique) | + (si myocardite associée) |\n| Radiographie thoracique | Normale | Anormale (élargissement médiastinal) | ± anormale | Normale |\n\n> Les quatre plaintes cardinales (douleur thoracique, dyspnée, syncope, palpitations) peuvent être présentes dans chacune de ces quatre urgences : c'est leur association et leur contexte qui orientent le diagnostic, plus que la douleur prise isolément.","keyPoints":["Un mode de survenue brutal oriente vers un SCA ou une dissection, plus progressif vers l'EP.","L'horaire postprandial/décubitus/inspiration oriente vers la péricardite.","La radiographie thoracique est normale dans le SCA et la péricardite, anormale dans la dissection.","La troponine n'est indispensable que dans le SCA sans ST+, l'EP (pronostic) et la myopéricardite."],"pitfalls":["Se fier à un seul élément sémiologique isolé plutôt qu'à l'ensemble du tableau clinique."],"src":"p. 158"},{"id":"230-sec-08","title":"Douleurs chroniques d'origine cardiaque","rank":"A","objectives":["230-obj-12"],"content":"Les douleurs thoraciques chroniques d'origine cardiaque comprennent principalement l'angor stable, mais aussi des douleurs angineuses fonctionnelles.\n\n**Angor stable** : douleur pouvant être atypique dans son siège ou ses irradiations, parfois réduite aux seules irradiations. Elle est caractéristique lorsqu'elle est **constrictive**, déclenchée par l'effort (ou un repas), et cède à l'arrêt de l'effort ou après un spray de trinitrine en **1 à 3 minutes**.\n\n**[B] Autres douleurs angineuses chroniques** :\n- angor d'effort du rétrécissement aortique serré ;\n- angor fonctionnel de l'anémie, des tachycardies (fibrillation atriale), de l'hyperthyroïdie ;\n- douleur d'effort de la cardiomyopathie hypertrophique ;\n- douleur angineuse de certaines HTAP sévères, par souffrance ischémique du ventricule droit lorsque la pression intraventriculaire droite dépasse la pression de perfusion coronarienne.\n\n**[A] Démarche diagnostique devant une suspicion de syndrome coronarien chronique** : un score de probabilité clinique de maladie coronarienne combine :\n- les caractéristiques de la douleur thoracique/dyspnée (0 à 3 points) : 1 point si la douleur est typique, 1 point si elle est déclenchée par l'effort/le stress, 1 point si elle est calmée par le repos/la trinitrine en moins de 5 minutes ; 2 points si la dyspnée est le symptôme prédominant ;\n- le nombre de facteurs de risque cardiovasculaire (antécédent familial, HTA, tabac, dyslipidémie, diabète), coté de 0 à 5.\n\nStratégie selon la probabilité obtenue :\n- **< 5 %** : aucun examen complémentaire.\n- **5-15 %** : stratégie complexe — scanner coronaire d'emblée ou réévaluation à l'aide d'examens complémentaires (onde Q ou sous-ST à l'ECG de repos, troubles du rythme ventriculaire, épreuve d'effort anormale, altération de la FEVG à l'échocardiographie, score calcique élevé, atteinte vasculaire périphérique).\n- **15-50 %** : scanner coronarien ou imagerie fonctionnelle (scintigraphie, échographie de stress, IRM de stress), selon l'expérience du centre.\n- **> 50-85 %** : imagerie fonctionnelle.\n- **> 85 %** : coronarographie à titre diagnostique.","keyPoints":["L'angor stable typique est constrictif, à l'effort, cédant au repos ou à la trinitrine en 1-3 minutes.","Le rétrécissement aortique serré, la CMH, l'anémie, les tachycardies et l'hyperthyroïdie peuvent donner un angor fonctionnel.","Le score de probabilité clinique combine caractéristiques douleur/dyspnée et facteurs de risque CV.","Sous 5 % de probabilité, aucun examen n'est nécessaire ; au-delà de 85 %, coronarographie diagnostique d'emblée."],"pitfalls":["Une douleur atypique dans son siège n'élimine pas un angor stable.","Négliger la zone grise 5-15 %, qui nécessite une stratégie diagnostique spécifique."],"src":"p. 158-159"},{"id":"230-sec-09","title":"Causes extracardiaques de douleur thoracique","rank":"A","objectives":["230-obj-13","230-obj-14"],"content":"En dehors des quatre urgences cardiovasculaires, de nombreuses causes extracardiaques peuvent expliquer une douleur thoracique aiguë.\n\n**Origine pulmonaire**\n- Pneumothorax : douleur pleurale, tympanisme, abolition du murmure vésiculaire, parfois dyspnée ; diagnostic par radiographie en expiration pour les formes partielles.\n- Épanchement pleural / douleurs pleurales chroniques (mésothéliome, pachypleurite) : douleur pleurale, matité ; diagnostic radiographique (ligne de Damoiseau), parfois clichés en décubitus latéral, ponction pleurale à visée diagnostique.\n- Pneumopathie infectieuse : douleur en coup de poignard de type pleural, fièvre, syndrome de condensation (souffle tubaire entouré de râles crépitants), opacité systématisée ou non avec bronchogramme aérien, épanchement pleural parfois associé.\n\n**Origine œsophagienne** : reflux gastro-œsophagien, œsophagite ; spasme œsophagien (douleur pseudo-angineuse déclenchée par la déglutition, parfois calmée par les dérivés nitrés — piège classique) ; dysphagie ; rupture œsophagienne, exceptionnelle.\n\n**Origine pariétale (musculaire ou squelettique)** : syndrome de Tietze (douleur reproduite par la palpation costo-sternale) ; lésions sternales, arthralgies chondrocostales ; fractures costales (parfois pathologiques sur métastase ou myélome) ; douleur musculoligamentaire.\n\n**Origine neurologique** : zona intercostal, tassement vertébral.\n\n**Origine abdominale projetée** : lithiase vésiculaire, ulcère gastroduodénal, pancréatite aiguë, appendicite sous-hépatique, abcès sous-phrénique.\n\n**Origine psychogène** : très fréquente, associée à angoisse ou névrose ; diagnostic à porter avec prudence, après élimination des causes organiques.\n\n> Parmi ces causes, **six urgences non cardiaques** sont à identifier systématiquement : pleurésies/pneumonies, pneumothorax, pancréatite aiguë, ulcère gastroduodénal compliqué, cholécystite, douleurs radiculaires. Pour les autres étiologies, il n'y a pas d'urgence vitale, mais il faut rassurer et soulager rapidement le patient.\n\nÀ l'inverse, un infarctus du myocarde inférieur peut mimer une gastro-entérite, et une ischémie mésentérique peut compliquer une dissection aortique : deux pièges classiques à connaître.","keyPoints":["Les 4 P extracardiaques à retenir : pneumonie, pleurésie, pneumothorax, pancréatite.","6 urgences non cardiaques : pleurésie/pneumonie, pneumothorax, pancréatite aiguë, ulcère compliqué, cholécystite, douleur radiculaire.","Le spasme œsophagien peut être calmé par les dérivés nitrés, comme un angor : piège diagnostique.","Le diagnostic de douleur psychogène doit rester un diagnostic d'élimination, posé avec prudence."],"pitfalls":["Un infarctus du myocarde inférieur peut mimer une gastro-entérite.","Une dissection aortique peut se compliquer d'une ischémie mésentérique trompeuse.","Attribuer trop vite une douleur thoracique à l'anxiété sans avoir éliminé les urgences organiques."],"src":"p. 159-162"}],"essentials":[{"id":"230-ess-01","rank":"A","text":"Devant une douleur thoracique aiguë, la première étape est toujours la recherche d'une détresse vitale (respiratoire, hémodynamique, neurologique).","src":"p. 151"},{"id":"230-ess-02","rank":"A","text":"Une polypnée > 30/min ou une bradypnée < 10/min signent une détresse respiratoire.","src":"p. 151"},{"id":"230-ess-03","rank":"A","text":"Une SpO2 < 90 % témoigne d'une désaturation évocatrice de détresse respiratoire.","src":"p. 151"},{"id":"230-ess-04","rank":"A","text":"Le mnémotechnique PIED regroupe les 4 urgences cardiovasculaires : Péricardite, Infarctus, Embolie pulmonaire, Dissection.","src":"p. 153"},{"id":"230-ess-05","rank":"A","text":"La rupture de l'œsophage, exceptionnelle, doit être évoquée devant une douleur thoracique associée à dyspnée, emphysème sous-cutané ou pneumomédiastin.","src":"p. 153"},{"id":"230-ess-06","rank":"A","text":"Devant une suspicion des 4 urgences cardiovasculaires, ECG, radiographie pulmonaire et troponine ultrasensible sont systématiques.","src":"p. 153"},{"id":"230-ess-07","rank":"A","text":"L'ECG doit inclure les dérivations V3R, V4R, V7, V8, V9 devant une douleur thoracique aiguë suspecte.","src":"p. 153"},{"id":"230-ess-08","rank":"A","text":"Un SCA avec sus-décalage persistant du ST impose un transfert médicalisé direct vers la coronarographie ou l'USIC.","src":"p. 153"},{"id":"230-ess-09","rank":"A","text":"L'infarctus est à évoquer dès que la douleur dépasse 20 minutes.","src":"p. 154"},{"id":"230-ess-10","rank":"A","text":"Une dyspnée accompagne le SCA dans environ 10 % des cas.","src":"p. 154"},{"id":"230-ess-11","rank":"A","text":"Un bloc de branche gauche nouveau doit être considéré comme un équivalent de SCA avec sus-décalage du ST.","src":"p. 154"},{"id":"230-ess-12","rank":"A","text":"Les ischémies de l'artère circonflexe peuvent être électriquement muettes sur l'ECG standard : penser à V7-V8-V9.","src":"p. 154"},{"id":"230-ess-13","rank":"A","text":"Dans le SCA ST+, le dosage de la troponine ne doit jamais retarder la reperfusion.","src":"p. 155"},{"id":"230-ess-14","rank":"A","text":"Dans le SCA sans ST+, une cinétique significative de la troponine entre H0 et H1-H2 signe un SCA à haut risque.","src":"p. 155"},{"id":"230-ess-15","rank":"B","text":"Une asymétrie tensionnelle supérieure à 20 mmHg évoque une dissection aortique.","src":"p. 155"},{"id":"230-ess-16","rank":"B","text":"Le score de probabilité clinique de dissection aortique comporte 3 critères d'1 point chacun : terrain, douleur, examen clinique.","src":"p. 155"},{"id":"230-ess-17","rank":"B","text":"La probabilité de dissection aortique est faible pour un score de 0-1 et forte pour un score de 2-3.","src":"p. 155"},{"id":"230-ess-18","rank":"B","text":"L'angioscanner thoracique est souvent nécessaire au diagnostic positif et à la planification chirurgicale d'une dissection aortique.","src":"p. 156"},{"id":"230-ess-19","rank":"B","text":"La dissection de type A de Stanford (aorte ascendante) impose une chirurgie en urgence.","src":"p. 156"},{"id":"230-ess-20","rank":"A","text":"La pression artérielle doit être normalisée en urgence en cas de dissection aortique, qui est une urgence hypertensive.","src":"p. 156"},{"id":"230-ess-21","rank":"A","text":"L'embolie pulmonaire est évoquée devant l'association douleur, dyspnée et radiographie thoracique normale.","src":"p. 156"},{"id":"230-ess-22","rank":"A","text":"Les signes ECG classiques de l'embolie pulmonaire sont S1Q3, bloc de branche droit et ondes T négatives en V1-V3.","src":"p. 156"},{"id":"230-ess-23","rank":"A","text":"Une PAS < 90 mmHg ou une chute de PAS > 40 mmHg pendant plus de 15 minutes définit l'embolie pulmonaire à haut risque.","src":"p. 156"},{"id":"230-ess-24","rank":"A","text":"Des D-dimères positifs se définissent par un seuil supérieur à 500 µg/L, ou supérieur à 10 fois l'âge après 50 ans (ESC 2019).","src":"p. 157"},{"id":"230-ess-25","rank":"A","text":"En cas de forte probabilité clinique d'embolie pulmonaire, le dosage des D-dimères est inutile : l'angioscanner est demandé d'emblée.","src":"p. 157"},{"id":"230-ess-26","rank":"A","text":"La péricardite aiguë donne une douleur augmentée par l'inspiration et le décubitus, calmée par l'antéflexion.","src":"p. 157"},{"id":"230-ess-27","rank":"A","text":"L'ECG de péricardite montre un sus-décalage du ST concave et diffus sans miroir, associé à un sous-décalage du segment PQ.","src":"p. 157"},{"id":"230-ess-28","rank":"A","text":"La péricardite aiguë est un diagnostic d'élimination, la plus bénigne des 4 urgences cardiovasculaires.","src":"p. 157"},{"id":"230-ess-29","rank":"A","text":"La tamponnade se manifeste par des signes droits, un état de choc et un pouls paradoxal.","src":"p. 157"},{"id":"230-ess-30","rank":"A","text":"Le pouls paradoxal correspond à une chute de la PAS à l'inspiration supérieure à 10 mmHg par rapport à l'expiration.","src":"p. 157"},{"id":"230-ess-31","rank":"B","text":"La myopéricardite s'accompagne d'une élévation prolongée de la troponine et peut mimer un SCA, mais la coronarographie est normale.","src":"p. 158"},{"id":"230-ess-32","rank":"A","text":"L'angor stable typique est constrictif, déclenché par l'effort, cédant au repos ou à la trinitrine en 1 à 3 minutes.","src":"p. 158-159"},{"id":"230-ess-33","rank":"B","text":"Le rétrécissement aortique serré, la cardiomyopathie hypertrophique, l'anémie, les tachycardies et l'hyperthyroïdie peuvent donner un angor fonctionnel.","src":"p. 152, 159"},{"id":"230-ess-34","rank":"A","text":"Le score de probabilité clinique de coronaropathie chronique combine caractéristiques de la douleur/dyspnée (0-3 points) et facteurs de risque cardiovasculaire (0-5 points).","src":"p. 159"},{"id":"230-ess-35","rank":"A","text":"Sous 5 % de probabilité clinique de coronaropathie chronique, aucun examen complémentaire n'est nécessaire.","src":"p. 159"},{"id":"230-ess-36","rank":"A","text":"Au-delà de 85 % de probabilité clinique de coronaropathie chronique, une coronarographie diagnostique est indiquée d'emblée.","src":"p. 159"},{"id":"230-ess-37","rank":"A","text":"Les causes thoraciques extracardiaques les plus fréquentes se résument par les 4 P : pneumonie, pleurésie, pneumothorax, pancréatite.","src":"p. 162"},{"id":"230-ess-38","rank":"A","text":"Six urgences non cardiaques sont à identifier devant une douleur thoracique : pleurésie/pneumonie, pneumothorax, pancréatite aiguë, ulcère compliqué, cholécystite, douleur radiculaire.","src":"p. 161"},{"id":"230-ess-39","rank":"B","text":"Le spasme œsophagien peut mimer un angor et être calmé, comme lui, par les dérivés nitrés.","src":"p. 160"},{"id":"230-ess-40","rank":"A","text":"Le diagnostic de douleur thoracique psychogène doit rester un diagnostic d'élimination, posé avec prudence.","src":"p. 160-162"}],"numbers":[{"id":"230-num-01","rank":"A","label":"Polypnée évocatrice de détresse respiratoire","value":"FR > 30/min","src":"p. 151"},{"id":"230-num-02","rank":"A","label":"Bradypnée évocatrice de détresse respiratoire","value":"FR < 10/min ou pause respiratoire","src":"p. 151"},{"id":"230-num-03","rank":"A","label":"Désaturation évocatrice de détresse respiratoire","value":"SpO2 < 90 %","src":"p. 151"},{"id":"230-num-04","rank":"A","label":"Durée de douleur évocatrice d'infarctus du myocarde","value":"> 20 minutes","src":"p. 154"},{"id":"230-num-05","rank":"A","label":"Fréquence de la dyspnée associée au SCA","value":"≈ 10 % des cas","src":"p. 154"},{"id":"230-num-06","rank":"B","label":"Asymétrie tensionnelle évocatrice de dissection aortique","value":"> 20 mmHg","src":"p. 155"},{"id":"230-num-07","rank":"B","label":"Score de probabilité clinique de dissection aortique","value":"3 critères, 1 point chacun (score de 0 à 3)","src":"p. 155"},{"id":"230-num-08","rank":"B","label":"Probabilité clinique de dissection aortique jugée faible","value":"score de 0 ou 1","src":"p. 155"},{"id":"230-num-09","rank":"B","label":"Probabilité clinique de dissection aortique jugée forte","value":"score de 2 ou 3","src":"p. 155"},{"id":"230-num-10","rank":"A","label":"Seuil de positivité des D-dimères pour l'embolie pulmonaire","value":"> 500 µg/L, ou > 10 × l'âge après 50 ans (ESC 2019)","src":"p. 157"},{"id":"230-num-11","rank":"A","label":"Définition de l'hypotension dans l'embolie pulmonaire à haut risque","value":"PAS < 90 mmHg ou chute > 40 mmHg pendant plus de 15 minutes","src":"p. 156"},{"id":"230-num-12","rank":"A","label":"Pouls paradoxal de la tamponnade péricardique","value":"chute de la PAS à l'inspiration > 10 mmHg par rapport à l'expiration","src":"p. 157"},{"id":"230-num-13","rank":"A","label":"Délai de soulagement de l'angor stable par la trinitrine","value":"1 à 3 minutes","src":"p. 158-159"},{"id":"230-num-14","rank":"A","label":"Score de probabilité clinique de coronaropathie chronique — item douleur/dyspnée","value":"0 à 3 points (2 points si dyspnée prédominante)","src":"p. 159"},{"id":"230-num-15","rank":"A","label":"Score de probabilité clinique de coronaropathie chronique — facteurs de risque cardiovasculaire","value":"0 à 5 points","src":"p. 159"},{"id":"230-num-16","rank":"A","label":"Probabilité clinique de coronaropathie chronique très faible","value":"< 5 % : aucun examen complémentaire","src":"p. 159"},{"id":"230-num-17","rank":"A","label":"Probabilité clinique de coronaropathie chronique modérée","value":"15-50 % : scanner coronaire ou imagerie fonctionnelle","src":"p. 159"},{"id":"230-num-18","rank":"A","label":"Probabilité clinique de coronaropathie chronique élevée","value":"> 50-85 % : imagerie fonctionnelle","src":"p. 159"},{"id":"230-num-19","rank":"A","label":"Probabilité clinique de coronaropathie chronique très élevée","value":"> 85 % : coronarographie diagnostique","src":"p. 159"},{"id":"230-num-20","rank":"A","label":"Zone grise de probabilité clinique de coronaropathie chronique","value":"5-15 %","src":"p. 159"},{"id":"230-num-21","rank":"A","label":"Dérivations ECG systématiques devant une douleur thoracique aiguë suspecte","value":"12 dérivations standard + V3R, V4R, V7, V8, V9","src":"p. 153"},{"id":"230-num-22","rank":"A","label":"Nombre d'urgences cardiovasculaires à évoquer systématiquement","value":"4 (mnémotechnique PIED)","src":"p. 153"},{"id":"230-num-23","rank":"A","label":"Nombre d'urgences non cardiaques à identifier devant une douleur thoracique","value":"6","src":"p. 161"},{"id":"230-num-24","rank":"A","label":"Causes thoraciques extracardiaques les plus fréquentes","value":"4 P : pneumonie, pleurésie, pneumothorax, pancréatite","src":"p. 162"}],"mnemonics":[{"id":"230-mn-01","rank":"A","title":"PIED — les quatre urgences cardiovasculaires","mnemonic":"PIED","expansion":"- **P**éricardite aiguë (avec risque de tamponnade)\n- **I**nfarctus du myocarde / syndrome coronarien aigu\n- **E**mbolie pulmonaire\n- **D**issection aortique","src":"p. 153"},{"id":"230-mn-02","rank":"A","title":"Les 4 P des causes thoraciques extracardiaques","mnemonic":"4 P","expansion":"- **P**neumonie\n- **P**leurésie\n- **P**neumothorax\n- **P**ancréatite","src":"p. 162"},{"id":"230-mn-03","rank":"A","title":"TRAC — signes de détresse respiratoire","mnemonic":"TRAC","expansion":"- **T**irage (muscles respiratoires accessoires)\n- **R**ythme respiratoire anormal (polypnée > 30/min ou bradypnée < 10/min)\n- **A**ltération cutanéo-muqueuse : sueurs, cyanose, désaturation (SpO2 < 90 %)\n- **C**onfusion / encéphalopathie respiratoire","src":"p. 151"},{"id":"230-mn-04","rank":"B","title":"TDE — score de probabilité clinique de dissection aortique","mnemonic":"TDE","expansion":"- **T**errain évocateur (Marfan, ATCD familial, anévrisme/valvulopathie aortique, chirurgie aortique)\n- **D**ouleur évocatrice (brutale, intense, en déchirement)\n- **E**xamen clinique évocateur (abolition de pouls, asymétrie tensionnelle, déficit neuro, souffle d'IA, choc)","src":"p. 155"},{"id":"230-mn-05","rank":"B","title":"RCATH — causes d'angor fonctionnel","mnemonic":"RCATH","expansion":"- **R**étrécissement aortique serré\n- **C**ardiomyopathie hypertrophique\n- **A**némie\n- **T**achycardies (fibrillation atriale)\n- **H**yperthyroïdie","src":"p. 152, 159"},{"id":"230-mn-06","rank":"B","title":"SADI — signes cliniques évocateurs de dissection aortique","mnemonic":"SADI","expansion":"- **S**ouffle d'insuffisance aortique\n- **A**symétrie tensionnelle\n- **D**éficit neurologique focal\n- **I**schémie de pouls (abolition d'un pouls)","src":"p. 155"},{"id":"230-mn-07","rank":"A","title":"LUPAA — causes abdominales projetées de douleur thoracique","mnemonic":"LUPAA","expansion":"- **L**ithiase vésiculaire\n- **U**lcère gastroduodénal\n- **P**ancréatite aiguë\n- **A**ppendicite sous-hépatique\n- **A**bcès sous-phrénique","src":"p. 160"}]},"questions":[{"id":"230-qcm-001","type":"QRM","rank":"A","objective":"230-obj-02","tags":["urgence","clinique"],"difficulty":1,"stem":"Un homme de 54 ans consulte pour une douleur thoracique brutale. Il présente une fréquence respiratoire à 34/min, un tirage intercostal, une SpO2 à 87 % et des marbrures des genoux. Parmi les éléments suivants, lesquels témoignent d'une détresse vitale imposant une prise en charge thérapeutique immédiate ?","options":[{"t":"Une fréquence respiratoire à 34/min","ok":true,"why":"Une polypnée supérieure à 30/min est l'un des signes retenus pour la détresse respiratoire."},{"t":"Une SpO2 à 87 %","ok":true,"why":"Une SpO2 inférieure à 90 % traduit une désaturation évocatrice de détresse respiratoire."},{"t":"Un tirage intercostal","ok":true,"why":"La mise en jeu des muscles respiratoires accessoires signe une détresse respiratoire."},{"t":"Des marbrures des genoux","ok":true,"why":"Les marbrures traduisent une hypoperfusion périphérique, élément de l'état de choc."},{"t":"Une douleur cotée à 9/10 sur l'échelle visuelle analogique","ok":false,"why":"L'intensité seule de la douleur ne figure pas parmi les critères de détresse vitale décrits dans le chapitre."}],"explanation":"La détresse vitale doit être recherchée avant toute caractérisation fine de la douleur : elle regroupe les détresses respiratoire, hémodynamique et neurologique, et impose des mesures thérapeutiques immédiates.","trap":"Une douleur très intense n'est pas en soi un critère de détresse vitale : il faut rechercher activement les signes respiratoires, hémodynamiques et neurologiques.","src":"p. 151"},{"id":"230-qcm-002","type":"QRM","rank":"A","objective":"230-obj-03","tags":["urgence"],"difficulty":1,"stem":"Chez un patient présentant une douleur thoracique aiguë, dans quelle situation le transfert doit-il impérativement être médicalisé, via un appel au 15 ?","options":[{"t":"Devant un tableau évocateur de syndrome coronarien aigu","ok":true,"why":"Ne pas recourir au 15 devant un tableau évocateur de SCA est considéré comme une faute grave, du fait du risque de fibrillation ventriculaire et de la mortalité préhospitalière élevée."},{"t":"Devant une douleur pariétale reproduite par la palpation costale","ok":false,"why":"Une douleur pariétale n'est pas une urgence vitale et ne justifie pas de transfert médicalisé en urgence."},{"t":"Devant une douleur calmée par la prise d'un antiacide","ok":false,"why":"Une douleur soulagée par un antiacide oriente vers une cause digestive bénigne, sans urgence vitale."},{"t":"Devant une douleur anxieuse chez un patient déjà exploré et rassuré","ok":false,"why":"Une douleur psychogène, diagnostic d'élimination, ne justifie pas de transfert médicalisé en urgence."},{"t":"Devant une douleur reproduite par un mouvement du tronc","ok":false,"why":"Une douleur reproduite par la mobilisation oriente vers une cause pariétale bénigne."}],"explanation":"Le transfert d'un patient douloureux thoracique doit être médicalisé via le 15 devant tout tableau évocateur de syndrome coronarien, en raison du risque de fibrillation ventriculaire et de la mortalité préhospitalière élevée.","src":"p. 151"},{"id":"230-qru-001","type":"QRU","rank":"A","objective":"230-obj-04","tags":["urgence","diagnostic"],"difficulty":1,"stem":"Le moyen mnémotechnique « PIED » permet de retenir les quatre urgences cardiovasculaires à évoquer systématiquement devant une douleur thoracique aiguë. Laquelle des pathologies suivantes n'en fait pas partie ?","options":[{"t":"Péricardite aiguë","ok":false,"why":"Correspond au P de PIED."},{"t":"Infarctus du myocarde","ok":false,"why":"Correspond au I de PIED."},{"t":"Embolie pulmonaire","ok":false,"why":"Correspond au E de PIED."},{"t":"Dissection aortique","ok":false,"why":"Correspond au D de PIED."},{"t":"Pneumothorax","ok":true,"why":"Le pneumothorax est une cause extracardiaque de douleur thoracique, distincte des quatre urgences cardiovasculaires regroupées sous PIED."}],"explanation":"PIED regroupe péricardite, infarctus, embolie pulmonaire et dissection aortique ; le pneumothorax est l'une des causes extracardiaques à rechercher séparément.","src":"p. 153"},{"id":"230-qcm-003","type":"QRM","rank":"A","objective":"230-obj-05","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Un homme de 60 ans hypertendu de longue date présente une douleur thoracique brutale à type de déchirement, migrant vers le dos puis les lombes. Parmi les caractéristiques suivantes, lesquelles sont évocatrices d'une dissection aortique ?","options":[{"t":"Le caractère migrateur de la douleur vers les lombes","ok":true,"why":"La migration de la douleur vers les lombes est un élément sémiologique classique de la dissection aortique."},{"t":"Le caractère de déchirement de la douleur","ok":true,"why":"La douleur en déchirement est typique de la dissection aortique."},{"t":"Une irradiation postérieure dans le dos","ok":true,"why":"La douleur de dissection irradie classiquement dans le dos."},{"t":"Un soulagement de la douleur après un repas","ok":false,"why":"Ce caractère postprandial oriente plutôt vers une cause digestive, non vers la dissection."},{"t":"Une douleur augmentée par l'inspiration profonde","ok":false,"why":"Ce caractère pleurétique oriente vers une péricardite ou une cause pleurale, non vers la dissection."}],"explanation":"La dissection aortique donne classiquement une douleur brutale, intense, en déchirement, migratrice, descendant vers les lombes et irradiant dans le dos.","src":"p. 155"},{"id":"230-qcm-004","type":"QRM","rank":"A","objective":"230-obj-06","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Concernant la démarche diagnostique commune aux quatre urgences cardiovasculaires devant une douleur thoracique aiguë, quelle proposition est exacte ?","options":[{"t":"Le dosage de la troponine doit être réalisé avant l'ECG","ok":false,"why":"L'ECG doit toujours précéder le dosage de la troponine ; l'inverse constitue une erreur reconnue."},{"t":"Le terrain, la douleur et les particularités de l'examen clinique orientent conjointement le diagnostic","ok":true,"why":"La démarche diagnostique combine le terrain évocateur, les caractéristiques de la douleur et les particularités de l'examen clinique."},{"t":"L'examen clinique est habituellement ininterprétable devant une urgence cardiovasculaire","ok":false,"why":"L'examen clinique, même parfois pauvre, reste toujours porteur d'informations utiles (pouls, souffles, signes droits)."},{"t":"La radiographie thoracique suffit à elle seule à écarter les quatre urgences cardiovasculaires","ok":false,"why":"La radiographie seule ne permet pas d'écarter les quatre urgences ; elle s'intègre dans un faisceau d'arguments."},{"t":"Le terrain n'intervient pas dans l'orientation diagnostique","ok":false,"why":"Le terrain, comme les facteurs de risque cardiovasculaire ou un contage viral, est au contraire un élément clé de l'orientation."}],"explanation":"Devant les quatre urgences cardiovasculaires, le terrain évocateur, les caractéristiques de la douleur thoracique et les particularités de l'examen clinique orientent ensemble le diagnostic.","src":"p. 151-153"},{"id":"230-qru-002","type":"QRU","rank":"A","objective":"230-obj-07","tags":["ECG","diagnostic","pièges"],"difficulty":3,"stem":"Un patient présente une douleur thoracique prolongée avec un sous-décalage isolé du segment ST de V2 à V4, sans autre anomalie sur les dérivations standards. Quelle interprétation faut-il privilégier ?","options":[{"t":"ECG normal, un syndrome coronarien aigu est éliminé","ok":false,"why":"Ce sous-décalage antérieur n'est pas un ECG normal et n'élimine rien."},{"t":"Ischémie du territoire circonflexe, à traiter comme un syndrome coronarien aigu avec sus-décalage du ST","ok":true,"why":"Un sous-décalage de V2 à V4 associé à une douleur prolongée peut traduire une occlusion circonflexe électriquement muette en face antérieure, à prendre en charge comme un ST+."},{"t":"Embolie pulmonaire","ok":false,"why":"L'EP donne plutôt un aspect S1Q3, un bloc de branche droit ou des ondes T négatives en précordial droit, pas ce sous-décalage."},{"t":"Péricardite aiguë","ok":false,"why":"La péricardite donne un sus-décalage concave diffus, non un sous-décalage antérieur localisé."},{"t":"Artefact d'enregistrement sans signification pathologique","ok":false,"why":"Ce sous-décalage a au contraire une signification pathologique majeure et impose une prise en charge urgente."}],"explanation":"Une ischémie de l'artère circonflexe peut être électriquement muette sur les dérivations standards ou se traduire par un sous-décalage de V2 à V4 : elle doit alors être traitée comme un SCA avec sus-décalage du ST.","trap":"Ne pas confondre un sous-décalage antérieur isolé avec un ECG rassurant : penser à l'occlusion circonflexe et enregistrer V7-V8-V9.","src":"p. 154"},{"id":"230-qcm-005","type":"QRM","rank":"A","objective":"230-obj-07","tags":["ECG"],"difficulty":1,"stem":"Quelles anomalies électrocardiographiques peuvent être observées au cours d'une embolie pulmonaire ?","options":[{"t":"Un aspect S1Q3","ok":true,"why":"L'aspect S1Q3 est un signe électrique classique de cœur pulmonaire aigu."},{"t":"Un bloc de branche droit","ok":true,"why":"Le bloc de branche droit fait partie des anomalies électriques de l'embolie pulmonaire."},{"t":"Des ondes T négatives dans les précordiales droites","ok":true,"why":"Des ondes T négatives en V1-V3 sont décrites au cours de l'embolie pulmonaire."},{"t":"Un sus-décalage du segment ST concave et diffus","ok":false,"why":"Ce sus-décalage concave diffus est caractéristique de la péricardite, non de l'embolie pulmonaire."},{"t":"Une tachycardie sinusale","ok":true,"why":"La tachycardie sinusale est le signe électrique le plus fréquent de l'embolie pulmonaire."}],"explanation":"L'ECG de l'embolie pulmonaire associe le plus souvent une tachycardie sinusale, un aspect S1Q3, un bloc de branche droit et des ondes T négatives en précordial droit.","src":"p. 156"},{"id":"230-qru-003","type":"QRU","rank":"A","objective":"230-obj-07","tags":["ECG","diagnostic"],"difficulty":1,"stem":"Quel signe électrocardiographique est le plus évocateur d'une péricardite aiguë non compliquée ?","options":[{"t":"Sus-décalage du segment ST concave, diffus, sans miroir","ok":true,"why":"C'est l'anomalie électrocardiographique typique de la péricardite aiguë."},{"t":"Sus-décalage du segment ST convexe, systématisé à un territoire coronaire","ok":false,"why":"Ce profil convexe et systématisé est typique d'un SCA avec sus-décalage du ST."},{"t":"Aspect S1Q3","ok":false,"why":"L'aspect S1Q3 est évocateur d'embolie pulmonaire."},{"t":"Bloc de branche gauche nouveau","ok":false,"why":"Un bloc de branche gauche nouveau est un équivalent de SCA avec sus-décalage du ST."},{"t":"Ondes Q de nécrose","ok":false,"why":"Les ondes Q orientent vers une séquelle d'infarctus, non vers une péricardite."}],"explanation":"La péricardite aiguë se traduit à l'ECG par un sus-décalage du ST concave, diffus ou non systématisé, sans miroir ni onde Q, associé à un sous-décalage du segment PQ.","src":"p. 157"},{"id":"230-qcm-006","type":"QRM","rank":"A","objective":"230-obj-08","tags":["imagerie","diagnostic"],"difficulty":2,"stem":"Concernant la radiographie thoracique dans le bilan d'une douleur thoracique aiguë, quelles associations sont exactes ?","options":[{"t":"Un élargissement du médiastin oriente vers une dissection aortique","ok":true,"why":"L'élargissement du médiastin est un signe radiographique classique de dissection aortique."},{"t":"Une radiographie strictement normale associée à une douleur et une dyspnée doit faire évoquer une embolie pulmonaire","ok":true,"why":"L'association douleur, dyspnée et radiographie normale doit faire évoquer obligatoirement le diagnostic d'embolie pulmonaire."},{"t":"Une cardiomégalie en « carafe » est évocatrice de tamponnade péricardique","ok":true,"why":"L'aspect cardiomégalique en carafe correspond à un épanchement péricardique abondant de la tamponnade."},{"t":"La radiographie thoracique est le plus souvent anormale dans le syndrome coronarien aigu typique","ok":false,"why":"La radiographie thoracique est normale et souvent inutile dans les tableaux typiques de SCA sans insuffisance cardiaque."},{"t":"Un aspect de double contour aortique évoque une dissection aortique","ok":true,"why":"Le double contour aortique est l'un des signes radiographiques de dissection aortique."}],"explanation":"La radiographie thoracique oriente différemment selon l'urgence en cause : élargissement médiastinal et double contour dans la dissection, cardiomégalie en carafe dans la tamponnade, normalité dans le SCA typique et la péricardite.","src":"p. 154-158"},{"id":"230-qru-004","type":"QRU","rank":"A","objective":"230-obj-09","tags":["biologie","urgence"],"difficulty":2,"stem":"Chez un patient présentant un sus-décalage persistant du segment ST à l'ECG en pleine douleur thoracique, quelle est l'attitude correcte concernant le dosage de la troponine ultrasensible ?","options":[{"t":"Il doit être réalisé et son résultat attendu avant toute reperfusion","ok":false,"why":"Attendre la troponine retarderait la reperfusion, ce qui est une faute reconnue."},{"t":"Il est inutile à la décision et ne doit jamais retarder la reperfusion","ok":true,"why":"Dans le SCA ST+ confirmé à l'ECG, le dosage de troponine est inutile à la décision et ne doit jamais retarder l'angioplastie ou la thrombolyse."},{"t":"Il doit être répété toutes les heures avant d'envisager une angioplastie","ok":false,"why":"Aucune répétition horaire n'est requise avant la reperfusion d'un ST+ confirmé."},{"t":"Il conditionne le choix entre angioplastie et thrombolyse","ok":false,"why":"Ce choix dépend du délai de prise en charge, pas du taux de troponine."},{"t":"Il permet d'éliminer un diagnostic différentiel avant la coronarographie","ok":false,"why":"Dans le ST+ confirmé à l'ECG, la coronarographie est engagée sans attendre ce dosage."}],"explanation":"Dans le SCA avec sus-décalage persistant du segment ST confirmé à l'ECG, le dosage de troponine est inutile à la décision thérapeutique et ne doit jamais retarder la reperfusion.","src":"p. 155"},{"id":"230-qcm-007","type":"QRM","rank":"A","objective":"230-obj-09","tags":["biologie","diagnostic"],"difficulty":2,"stem":"Chez un patient suspect de syndrome coronarien aigu sans sus-décalage persistant du segment ST, quelles propositions concernant la troponine ultrasensible sont exactes ?","options":[{"t":"Un premier dosage très faible sans cinétique significative au second dosage oriente vers un diagnostic différentiel ou un SCA à bas risque","ok":true,"why":"Une Tn-us initiale très faible ou faible sans augmentation significative au second dosage oriente vers un diagnostic différentiel ou un SCA à bas risque, surveillé en Usic."},{"t":"Une augmentation significative entre le premier et le second dosage pose le diagnostic de SCA à haut risque","ok":true,"why":"Une cinétique significative de la troponine entre les deux dosages signe un SCA sans ST+ à haut risque."},{"t":"Le second dosage est réalisé 1 à 2 heures après le premier","ok":true,"why":"Le second dosage de Tn-us est réalisé 1 à 2 heures après le premier dosage."},{"t":"Un dosage isolé unique suffit toujours à écarter le diagnostic","ok":false,"why":"Un dosage isolé ne suffit pas : c'est la cinétique entre deux dosages qui est déterminante."},{"t":"Ce dosage n'a aucun intérêt pronostique","ok":false,"why":"Le dosage de troponine a un intérêt à la fois diagnostique et pronostique dans le SCA sans ST+."}],"explanation":"Dans le SCA sans ST+ persistant, la cinétique de la troponine ultrasensible entre H0 et H1-H2 permet de distinguer un diagnostic à bas risque d'un SCA à haut risque.","src":"p. 155"},{"id":"230-qcm-008","type":"QRM","rank":"B","objective":"230-obj-10","tags":["traitement","urgence"],"difficulty":2,"stem":"En cas de syndrome coronarien aigu avec sus-décalage persistant du segment ST, quelle est la place de la coronarographie ?","options":[{"t":"Elle est réalisée en urgence, avec une place diagnostique et thérapeutique de première intention","ok":true,"why":"La coronarographie occupe une place à la fois diagnostique et thérapeutique de première intention dans le SCA ST+."},{"t":"Elle n'est indiquée qu'après un échec du traitement médical bien conduit","ok":false,"why":"Elle est au contraire réalisée d'emblée, sans délai, dès la confirmation du SCA ST+."},{"t":"Elle est contre-indiquée à la phase aiguë du SCA ST+","ok":false,"why":"C'est à l'inverse l'examen clé de la prise en charge immédiate du SCA ST+."},{"t":"Elle est réservée aux formes sans sus-décalage du segment ST","ok":false,"why":"C'est bien dans le SCA ST+ qu'elle a une place de première intention, diagnostique et thérapeutique."},{"t":"Elle doit systématiquement être précédée d'un scanner coronaire","ok":false,"why":"Aucun scanner coronaire préalable n'est requis avant une coronarographie en urgence pour un SCA ST+."}],"explanation":"Dans le SCA avec sus-décalage persistant du ST, la coronarographie a une place diagnostique et thérapeutique de première intention, réalisée en urgence via transfert médicalisé.","src":"p. 153"},{"id":"230-qcm-009","type":"QRM","rank":"B","objective":"230-obj-11","tags":["imagerie","diagnostic"],"difficulty":3,"stem":"Concernant l'imagerie de la dissection aortique, quelle proposition est exacte ?","options":[{"t":"L'échocardiographie transœsophagienne n'est réalisée qu'en cas de stabilité hémodynamique","ok":true,"why":"L'ETO n'est pratiquée que si l'état hémodynamique du patient le permet."},{"t":"L'angioscanner thoracique est rarement utile à la planification d'un geste chirurgical","ok":false,"why":"L'angioscanner est au contraire souvent nécessaire pour planifier un geste chirurgical (porte d'entrée, extension, atteintes vasculaires)."},{"t":"L'échocardiographie transthoracique ne permet jamais de poser le diagnostic","ok":false,"why":"L'échocardiographie transthoracique permet parfois de poser le diagnostic de dissection aortique."},{"t":"Le scanner thoracique est contre-indiqué chez un patient hémodynamiquement instable","ok":false,"why":"Le scanner reste un examen clé, y compris pour orienter la prise en charge des patients instables."},{"t":"L'imagerie n'a qu'un intérêt diagnostique, jamais pour la planification chirurgicale","ok":false,"why":"L'angioscanner renseigne aussi sur la porte d'entrée et l'extension de la dissection, utiles à la planification chirurgicale."}],"explanation":"L'ETO n'est réalisée qu'en cas de stabilité hémodynamique, tandis que l'angioscanner thoracique reste souvent indispensable au diagnostic positif comme à la planification d'un geste chirurgical.","src":"p. 156"},{"id":"230-qcm-010","type":"QRM","rank":"B","objective":"230-obj-12","tags":["étiologie","clinique"],"difficulty":2,"stem":"Devant un angor d'effort sans lésion coronaire significative, quelles causes d'angor fonctionnel sont citées par le référentiel ?","options":[{"t":"Rétrécissement aortique serré","ok":true,"why":"Le rétrécissement aortique serré est cité comme cause d'angor fonctionnel."},{"t":"Anémie","ok":true,"why":"L'anémie est citée parmi les causes d'angor fonctionnel."},{"t":"Fibrillation atriale","ok":true,"why":"Les tachycardies, notamment la fibrillation atriale, sont citées parmi les causes d'angor fonctionnel."},{"t":"Péricardite aiguë","ok":false,"why":"La péricardite aiguë est l'une des quatre urgences cardiovasculaires, non une cause d'angor fonctionnel."},{"t":"Hyperthyroïdie","ok":true,"why":"L'hyperthyroïdie est citée parmi les causes d'angor fonctionnel."}],"explanation":"Le rétrécissement aortique serré, la cardiomyopathie hypertrophique, l'anémie, les tachycardies (fibrillation atriale) et l'hyperthyroïdie sont les causes d'angor fonctionnel citées par le chapitre.","src":"p. 152, 158-159"},{"id":"230-qcm-011","type":"QRM","rank":"A","objective":"230-obj-13","tags":["étiologie","clinique"],"difficulty":1,"stem":"Parmi les causes suivantes, lesquelles doivent être évoquées comme causes thoraciques en dehors des quatre urgences cardiovasculaires devant une douleur thoracique aiguë ?","options":[{"t":"Pneumonie","ok":true,"why":"La pneumopathie infectieuse est l'une des causes thoraciques extracardiaques à connaître."},{"t":"Pneumothorax","ok":true,"why":"Le pneumothorax est cité comme cause thoracique en dehors des quatre urgences cardiovasculaires."},{"t":"Cardiomyopathie hypertrophique","ok":false,"why":"Il s'agit d'une cause de douleur chronique par angor fonctionnel, non d'une cause thoracique aiguë extracardiaque."},{"t":"Épanchement pleural","ok":true,"why":"L'épanchement pleural fait partie des douleurs d'origine pulmonaire à évoquer en dehors des quatre urgences cardiovasculaires."},{"t":"Dissection aortique","ok":false,"why":"La dissection aortique fait partie des quatre urgences cardiovasculaires elles-mêmes, non des causes en dehors."}],"explanation":"En dehors des quatre urgences cardiovasculaires, les causes thoraciques principales sont d'origine pulmonaire : pneumonie, pneumothorax et épanchement pleural notamment.","src":"p. 159-160"},{"id":"230-qcm-012","type":"QRM","rank":"A","objective":"230-obj-06","tags":["clinique","étiologie"],"difficulty":2,"stem":"Une patiente présente une douleur basithoracique avec une dyspnée aiguë et une radiographie thoracique strictement normale. Quel diagnostic doit être évoqué en priorité ?","options":[{"t":"Embolie pulmonaire","ok":true,"why":"L'association douleur, dyspnée et radiographie thoracique normale doit faire évoquer obligatoirement une embolie pulmonaire."},{"t":"Pneumopathie infectieuse","ok":false,"why":"Une pneumopathie infectieuse donne le plus souvent une opacité radiologique systématisée, non une radiographie normale."},{"t":"Pneumothorax","ok":false,"why":"Le pneumothorax se traduit par une hyperclarté ou une ligne pleurale visible à la radiographie, non par un cliché normal."},{"t":"Épanchement pleural","ok":false,"why":"Un épanchement pleural se traduit par une opacité radiologique, pas par un cliché strictement normal."},{"t":"Syndrome de Tietze","ok":false,"why":"Le syndrome de Tietze est une douleur pariétale reproduite par la palpation, sans dyspnée ni lien avec la radiographie."}],"explanation":"La triade douleur, dyspnée et radiographie thoracique normale doit systématiquement faire évoquer une embolie pulmonaire.","src":"p. 156"},{"id":"230-qcm-013","type":"QRM","rank":"A","objective":"230-obj-14","tags":["étiologie","clinique"],"difficulty":2,"stem":"Un patient présente une douleur thoracique basse projetée, dans un contexte de fièvre et de défense de l'hypochondre droit. Quelle cause abdominale projetée est la plus évocatrice ?","options":[{"t":"Cholécystite aiguë","ok":true,"why":"La cholécystite fait partie des causes abdominales projetées de douleur thoracique et des six urgences non cardiaques à connaître."},{"t":"Ulcère gastroduodénal non compliqué","ok":false,"why":"Un ulcère non compliqué ne s'accompagne pas typiquement de fièvre et de défense de l'hypochondre droit."},{"t":"Spasme œsophagien","ok":false,"why":"Le spasme œsophagien donne une douleur déclenchée par la déglutition, sans fièvre ni défense abdominale."},{"t":"Syndrome de Tietze","ok":false,"why":"Il s'agit d'une cause pariétale reproduite par la palpation costale, sans fièvre ni défense abdominale."},{"t":"Zona intercostal","ok":false,"why":"Le zona intercostal donne une douleur en hémiceinture avec éruption cutanée, sans défense de l'hypochondre droit."}],"explanation":"La cholécystite aiguë est l'une des causes abdominales projetées de douleur thoracique, et compte parmi les six urgences non cardiaques à identifier systématiquement.","src":"p. 160-161"},{"id":"230-qcm-014","type":"QRM","rank":"A","objective":"230-obj-06","tags":["clinique","diagnostic","pièges"],"difficulty":3,"stem":"Un homme de 68 ans, tabagique et diabétique, consulte pour des douleurs abdominales hautes avec nausées, sans franche douleur thoracique. Quel piège classique faut-il garder à l'esprit ?","options":[{"t":"Un infarctus du myocarde inférieur peut mimer une gastro-entérite","ok":true,"why":"Le chapitre souligne explicitement qu'un infarctus du myocarde inférieur peut mimer une gastro-entérite, d'où l'importance de ne pas méconnaître ce piège."},{"t":"Une pancréatite aiguë ne peut jamais se manifester par une douleur épigastrique","ok":false,"why":"La pancréatite aiguë se manifeste au contraire classiquement par une douleur abdominale projetée."},{"t":"Un ulcère gastroduodénal s'accompagne toujours d'une fièvre élevée","ok":false,"why":"Aucune fièvre élevée n'est décrite comme caractéristique de l'ulcère gastroduodénal dans ce chapitre."},{"t":"Une cholécystite exclut formellement toute origine cardiaque","ok":false,"why":"Une présentation digestive n'exclut pas une origine cardiaque, c'est précisément le piège à connaître."},{"t":"Un angor stable ne peut jamais siéger au niveau épigastrique","ok":false,"why":"La douleur coronarienne peut siéger de la mandibule à l'ombilic et mimer une douleur gastrique."}],"explanation":"Devant une présentation digestive trompeuse chez un patient à risque cardiovasculaire, il faut garder à l'esprit qu'un infarctus du myocarde inférieur peut mimer une gastro-entérite.","trap":"Une présentation abdominale ne doit jamais faire éliminer trop vite une cause cardiaque chez un patient à facteurs de risque.","src":"p. 162"},{"id":"230-qcm-015","type":"QRM","rank":"B","objective":"230-obj-09","tags":["biologie","diagnostic"],"difficulty":2,"stem":"Concernant le bilan biologique à demander devant une suspicion de dissection aortique, quelle proposition est exacte ?","options":[{"t":"Des D-dimères normaux rendent le diagnostic de dissection aortique rare, sans l'exclure formellement","ok":true,"why":"Le chapitre précise qu'il est rare d'avoir une dissection aortique avec des D-dimères normaux, sans que cela exclue formellement le diagnostic."},{"t":"Le dosage des CPK n'a aucun intérêt dans ce contexte","ok":false,"why":"Le dosage de la créatine-kinase est demandé pour dépister une éventuelle rhabdomyolyse associée."},{"t":"La créatininémie n'est pas utile au bilan initial","ok":false,"why":"La créatininémie fait partie du bilan biologique systématique de la dissection aortique."},{"t":"La troponine ultrasensible n'a pas sa place dans ce bilan","ok":false,"why":"La troponine ultrasensible est demandée pour rechercher une ischémie myocardique associée à la dissection."},{"t":"La NFS et les plaquettes ne sont pas nécessaires avant une éventuelle chirurgie","ok":false,"why":"La NFS et les plaquettes font partie du bilan systématique, notamment en vue d'une chirurgie éventuelle."}],"explanation":"Le bilan biologique de la dissection aortique comprend NFS, plaquettes, CRP, D-dimères, troponine ultrasensible, CPK et créatininémie ; des D-dimères normaux restent rares mais possibles.","src":"p. 156"},{"id":"230-qru-005","type":"QRU","rank":"A","objective":"230-obj-04","tags":["urgence","diagnostic"],"difficulty":2,"stem":"Une rupture de l'œsophage, cause exceptionnelle de douleur thoracique, doit être évoquée devant quelle association clinique ?","options":[{"t":"Douleur thoracique, dyspnée et emphysème sous-cutané ou pneumomédiastin","ok":true,"why":"C'est cette association clinique qui doit faire évoquer une rupture de l'œsophage, urgence thérapeutique bien que rare."},{"t":"Douleur thoracique isolée sans autre signe associé","ok":false,"why":"Aucun signe associé isolé n'oriente spécifiquement vers cette cause exceptionnelle."},{"t":"Douleur thoracique et syndrome inflammatoire biologique isolé","ok":false,"why":"Le syndrome inflammatoire isolé n'est pas l'élément d'orientation décrit pour la rupture de l'œsophage."},{"t":"Douleur thoracique et souffle diastolique d'insuffisance aortique","ok":false,"why":"Ce signe oriente plutôt vers une dissection aortique."},{"t":"Douleur thoracique et pouls paradoxal","ok":false,"why":"Le pouls paradoxal oriente vers une tamponnade péricardique, non vers une rupture œsophagienne."}],"explanation":"Bien qu'exceptionnelle, la rupture de l'œsophage doit être évoquée devant une douleur thoracique associée à une dyspnée, un emphysème sous-cutané ou un pneumomédiastin.","src":"p. 153"},{"id":"230-qroc-001","type":"QROC","rank":"A","objective":"230-obj-01","tags":["définition"],"difficulty":1,"question":"Comment définit-on, de façon générale, la démarche devant une douleur thoracique aiguë ?","answer":"Une douleur thoracique récente qui impose d'abord d'éliminer une détresse vitale, puis de rechercher les quatre urgences cardiovasculaires, avant toute autre caractérisation.","accept":["éliminer détresse vitale puis 4 urgences cardiovasculaires","démarche en deux temps"],"keywords":["détresse vitale","urgences cardiovasculaires"],"explanation":"La démarche devant une douleur thoracique aiguë suit toujours deux étapes : éliminer une détresse vitale, puis rechercher les quatre urgences cardiovasculaires avant d'envisager les autres causes.","src":"p. 151"},{"id":"230-qroc-002","type":"QROC","rank":"A","objective":"230-obj-04","tags":["diagnostic"],"difficulty":1,"question":"Que signifie le moyen mnémotechnique « PIED », utilisé pour retenir les quatre urgences cardiovasculaires devant une douleur thoracique ?","answer":"Péricardite, Infarctus du myocarde, Embolie pulmonaire, Dissection aortique.","accept":["péricardite infarctus embolie dissection","P I E D"],"keywords":["péricardite","infarctus","embolie","dissection"],"explanation":"PIED est le moyen mnémotechnique retenu pour les quatre urgences cardiovasculaires à évoquer systématiquement devant toute douleur thoracique aiguë.","src":"p. 153"},{"id":"230-qroc-003","type":"QROC","rank":"A","objective":"230-obj-06","tags":["diagnostic","clinique"],"difficulty":1,"question":"À partir de quelle durée une douleur thoracique doit-elle faire évoquer un infarctus du myocarde ?","answer":"Au-delà de 20 minutes.","accept":["20 min","plus de 20 minutes"],"keywords":["20","minutes"],"explanation":"L'infarctus du myocarde est à évoquer dès que la douleur dépasse 20 minutes, en particulier chez un patient porteur de facteurs de risque cardiovasculaire.","src":"p. 154"},{"id":"230-qroc-004","type":"QROC","rank":"A","objective":"230-obj-06","tags":["clinique","épidémiologie"],"difficulty":1,"question":"Dans quelle proportion approximative de syndromes coronariens aigus une dyspnée est-elle associée à la douleur thoracique ?","answer":"Environ 10 % des cas.","accept":["10%","10 pour cent"],"keywords":["10"],"explanation":"Une dyspnée accompagne la douleur thoracique du syndrome coronarien aigu dans environ 10 % des cas.","src":"p. 154"},{"id":"230-qroc-005","type":"QROC","rank":"A","objective":"230-obj-07","tags":["ECG"],"difficulty":2,"question":"Quelle anomalie électrocardiographique nouvelle doit être considérée comme un équivalent de syndrome coronarien aigu avec sus-décalage du segment ST ?","answer":"Un bloc de branche gauche complet apparu récemment.","accept":["BBG nouveau","bloc de branche gauche récent"],"keywords":["bloc","branche","gauche"],"explanation":"Un bloc de branche gauche nouveau doit être pris en charge comme un équivalent de SCA avec sus-décalage du ST, même en l'absence de sus-décalage visible.","src":"p. 154"},{"id":"230-qroc-006","type":"QROC","rank":"A","objective":"230-obj-07","tags":["ECG","pièges"],"difficulty":2,"question":"Quelles dérivations électrocardiographiques complémentaires faut-il enregistrer pour ne pas méconnaître une ischémie du territoire circonflexe électriquement muette ?","answer":"Les dérivations postérieures V7, V8, V9.","accept":["V7 V8 V9"],"keywords":["V7","V8","V9"],"explanation":"Une ischémie du territoire circonflexe peut être muette sur les dérivations standards ; il faut penser à enregistrer V7, V8 et V9 pour ne pas la méconnaître.","src":"p. 154"},{"id":"230-qroc-007","type":"QROC","rank":"B","objective":"230-obj-05","tags":["clinique","diagnostic"],"difficulty":2,"question":"Quel écart de pression artérielle entre les deux bras est évocateur d'une dissection aortique ?","answer":"Une différence supérieure à 20 mmHg.","accept":["> 20 mmHg","plus de 20 mmHg"],"keywords":["20","mmHg"],"explanation":"Une asymétrie tensionnelle supérieure à 20 mmHg entre les deux bras fait partie des signes cliniques évocateurs d'une dissection aortique.","src":"p. 155"},{"id":"230-qroc-008","type":"QROC","rank":"B","objective":"230-obj-06","tags":["diagnostic"],"difficulty":2,"question":"Combien de critères composent le score de probabilité clinique de dissection aortique, et combien de points vaut chacun ?","answer":"Trois critères (terrain évocateur, douleur évocatrice, examen clinique évocateur), chacun valant 1 point.","accept":["3 critères, 1 point chacun"],"keywords":["3","critères","1 point"],"explanation":"Le score de probabilité clinique de dissection aortique comporte trois catégories de critères, chacune valant 1 point, pour un score total de 0 à 3.","src":"p. 155"},{"id":"230-qroc-009","type":"QROC","rank":"A","objective":"230-obj-09","tags":["biologie"],"difficulty":2,"question":"Quel seuil de positivité des D-dimères est retenu chez un patient de plus de 50 ans suspect d'embolie pulmonaire, selon les recommandations citées ?","answer":"Supérieur à 500 µg/L, ou supérieur à 10 fois l'âge du patient (ESC 2019).","accept":["> 500 µg/L ou 10 x l'âge","500 microgrammes par litre"],"keywords":["500","age"],"explanation":"Chez les patients de plus de 50 ans, le seuil de positivité des D-dimères retenu par l'ESC 2019 est soit supérieur à 500 µg/L, soit supérieur à 10 fois l'âge du patient.","src":"p. 157"},{"id":"230-qroc-010","type":"QROC","rank":"A","objective":"230-obj-09","tags":["urgence","diagnostic"],"difficulty":2,"question":"Comment définit-on l'hypotension caractérisant une embolie pulmonaire à haut risque ?","answer":"Une PAS inférieure à 90 mmHg, ou une chute de PAS supérieure à 40 mmHg pendant plus de 15 minutes.","accept":["PAS<90","chute PAS>40mmHg pendant plus de 15min"],"keywords":["90","40","15"],"explanation":"L'embolie pulmonaire à haut risque est définie par une PAS inférieure à 90 mmHg ou une baisse de plus de 40 mmHg de la PAS pendant plus de 15 minutes, en dehors d'un trouble du rythme, d'une hypovolémie ou d'un sepsis.","src":"p. 156"},{"id":"230-qroc-011","type":"QROC","rank":"A","objective":"230-obj-07","tags":["clinique","urgence"],"difficulty":3,"question":"Comment se définit précisément le pouls paradoxal observé au cours de la tamponnade péricardique ?","answer":"Une chute de la pression artérielle systolique à l'inspiration supérieure à 10 mmHg par rapport à l'expiration.","accept":["chute PAS inspiration >10mmHg"],"keywords":["10","mmHg","inspiration"],"explanation":"Le pouls paradoxal correspond à une baisse de la PAS de plus de 10 mmHg lors de l'inspiration comparée à l'expiration, liée à la dilatation du ventricule droit comprimant le ventricule gauche.","src":"p. 157"},{"id":"230-qroc-012","type":"QROC","rank":"A","objective":"230-obj-12","tags":["clinique"],"difficulty":3,"question":"En combien de temps un angor stable typique est-il classiquement soulagé par un spray de trinitrine ?","answer":"En 1 à 3 minutes.","accept":["1-3 min","1 à 3 minutes"],"keywords":["1","3","minutes"],"explanation":"L'angor stable typique cède à l'arrêt de l'effort ou après un spray de trinitrine en 1 à 3 minutes ; un délai différent doit remettre le diagnostic en question.","src":"p. 158-159"},{"id":"230-open-01","type":"OPEN","rank":"A","objective":"230-obj-02","tags":["urgence","diagnostic"],"difficulty":2,"prompt":"Un patient de 50 ans se présente aux urgences pour une douleur thoracique d'apparition brutale il y a 30 minutes. Décrivez la démarche diagnostique structurée à suivre, depuis l'accueil du patient jusqu'à l'orientation étiologique initiale.","rubric":[{"point":"Rechercher en priorité une détresse vitale (respiratoire, hémodynamique, neurologique) avant toute caractérisation fine de la douleur","weight":3},{"point":"Citer des signes de détresse respiratoire (polypnée > 30/min ou bradypnée < 10/min, tirage, désaturation SpO2 < 90 %) et hémodynamique (arrêt circulatoire, état de choc)","weight":2},{"point":"Une fois la détresse vitale écartée, évoquer systématiquement les quatre urgences cardiovasculaires (PIED)","weight":2},{"point":"Prescrire les examens complémentaires systématiques : ECG 12 dérivations complété de V3R, V4R, V7, V8, V9, radiographie pulmonaire, troponine ultrasensible","weight":2},{"point":"Organiser un transfert médicalisé via le 15 devant tout tableau évocateur de syndrome coronarien aigu","weight":1}],"model":"### 1. Rechercher une détresse vitale\nAvant toute analyse fine de la douleur, il faut éliminer une détresse respiratoire (polypnée, tirage, désaturation), hémodynamique (choc, arrêt circulatoire) ou neurologique (confusion). Leur présence impose une prise en charge en réanimation ou en Usic immédiate.\n\n### 2. Rechercher les quatre urgences cardiovasculaires\nUne fois la détresse vitale écartée ou traitée, il faut évoquer systématiquement les quatre urgences regroupées sous PIED : péricardite, infarctus, embolie pulmonaire, dissection aortique.\n\n### 3. Examens complémentaires systématiques\nECG 12 dérivations complété par V3R, V4R, V7, V8, V9, radiographie pulmonaire et dosage de troponine ultrasensible sont demandés quelle que soit l'orientation clinique initiale.\n\n### 4. Orientation et transfert\nDevant un tableau évocateur de syndrome coronarien, le transfert doit être médicalisé, via le 15, avec orientation directe vers la coronarographie ou l'Usic en cas de sus-décalage persistant du ST.","src":"p. 151-153"},{"id":"230-open-02","type":"OPEN","rank":"A","objective":"230-obj-05","tags":["diagnostic","imagerie","biologie"],"difficulty":3,"prompt":"Un homme de 65 ans, hypertendu depuis 20 ans, présente une douleur thoracique brutale à type de coup de poignard, irradiant dans le dos, avec une asymétrie tensionnelle entre les deux bras. Décrivez la démarche diagnostique complète devant cette suspicion de dissection aortique.","rubric":[{"point":"Décrire les signes cliniques évocateurs : asymétrie tensionnelle > 20 mmHg, abolition d'un pouls, souffle d'insuffisance aortique, déficit neurologique focal","weight":2},{"point":"Citer l'utilisation d'un score de probabilité clinique à 3 critères (terrain, douleur, examen), chacun coté 1 point","weight":2},{"point":"Préciser que l'ECG peut être normal ou montrer un SCA en cas d'extension coronaire","weight":1},{"point":"Décrire les anomalies radiographiques possibles : élargissement médiastinal, double contour aortique","weight":1},{"point":"Citer le bilan biologique : NFS, plaquettes, CRP, D-dimères, troponine ultrasensible, CPK, créatininémie","weight":1},{"point":"Décrire la stratégie d'imagerie : échocardiographie (ETT/ETO selon stabilité), angioscanner thoracique souvent nécessaire au diagnostic et à la planification chirurgicale","weight":2},{"point":"Préciser les principes de prise en charge : chirurgie urgente si atteinte de l'aorte ascendante, traitement médical si type B non compliqué, normalisation tensionnelle en urgence","weight":2}],"model":"### Clinique\nRechercher une asymétrie tensionnelle supérieure à 20 mmHg, une abolition d'un pouls, un souffle d'insuffisance aortique, un déficit neurologique focal, ou une complication révélatrice (ischémie de membre, AVC, tableau abdominal trompeur, tamponnade).\n\n### Score de probabilité clinique\nTrois catégories de critères sont cotées 1 point chacune : terrain évocateur (Marfan, antécédent familial, anévrisme aortique connu, chirurgie aortique), douleur évocatrice (brutale, intense, en déchirement), examen évocateur (pouls aboli, asymétrie tensionnelle, déficit neuro, souffle d'IA, choc). Probabilité faible si 0-1, forte si 2-3.\n\n### ECG et radiographie\nL'ECG peut être normal ou montrer une ischémie si la dissection s'étend à une coronaire. La radiographie thoracique peut montrer un élargissement du médiastin, un épanchement pleural, un double contour aortique.\n\n### Biologie\nNFS, plaquettes, CRP, D-dimères, troponine ultrasensible, CPK, créatininémie ; des D-dimères normaux restent rares en cas de dissection.\n\n### Imagerie\nL'échocardiographie (ETT, ou ETO si stabilité hémodynamique) peut parfois suffire ; l'angioscanner thoracique reste souvent indispensable au diagnostic et à la planification chirurgicale (porte d'entrée, extension, atteintes vasculaires).\n\n### Prise en charge\nChirurgie en urgence en cas d'atteinte de l'aorte ascendante (type A de Stanford), traitement médical pour les formes limitées à l'aorte descendante non compliquées (type B). La pression artérielle doit être normalisée en urgence, la dissection étant une urgence hypertensive.","src":"p. 155-156"},{"id":"230-open-03","type":"OPEN","rank":"A","objective":"230-obj-06","tags":["diagnostic","ECG"],"difficulty":2,"prompt":"Comparez la péricardite aiguë non compliquée, la tamponnade péricardique et la myopéricardite sur le plan clinique, électrocardiographique et échocardiographique.","rubric":[{"point":"Péricardite non compliquée : douleur positionnelle (majorée en décubitus/inspiration, calmée par l'antéflexion), frottement fugace, sus-ST concave diffus sans miroir, sous-PQ, diagnostic le plus bénin et d'élimination","weight":3},{"point":"Tamponnade : urgence vitale, signes droits, choc, pouls paradoxal, microvoltage voire alternance électrique, cardiomégalie en carafe","weight":3},{"point":"Echocardiographie de la tamponnade : collapsus des cavités droites en expiration, compression du VG par le VD en inspiration, épanchement abondant","weight":2},{"point":"Myopéricardite : douleur pouvant mimer un SCA, troponine prolongée élevée, trouble cinétique segmentaire ou diffus du VG à l'échocardiographie, coronarographie normale","weight":2}],"model":"### Péricardite aiguë non compliquée\nDouleur augmentée par l'inspiration profonde et le décubitus, calmée par l'antéflexion du buste ; frottement péricardique fugace et inconstant ; ECG avec sus-ST concave diffus sans miroir et sous-décalage de PQ ; échocardiographie parfois normale (péricardite sèche) à répéter au besoin. C'est l'étiologie la plus bénigne des quatre urgences, diagnostic d'élimination.\n\n### Tamponnade péricardique\nÀ l'inverse, c'est une urgence vitale : dyspnée, orthopnée, signes droits (turgescence jugulaire, reflux hépatojugulaire), état de choc, pouls paradoxal (chute de la PAS à l'inspiration de plus de 10 mmHg). ECG : microvoltage, parfois alternance électrique. Radiographie : cardiomégalie en carafe. Échocardiographie : collapsus des cavités droites en expiration et compression du VG par le VD en inspiration, épanchement abondant.\n\n### Myopéricardite\nAtteinte myocardique associée, le plus souvent virale, pouvant mimer un SCA ; élévation prolongée de la troponine ; échocardiographie montrant un trouble cinétique segmentaire ou diffus du VG ; coronarographie normale ; l'IRM (œdème et rehaussement tardif sous-épicardique sans systématisation artérielle) aide à la différencier d'un infarctus.","src":"p. 157-158"},{"id":"230-open-04","type":"OPEN","rank":"A","objective":"230-obj-09","tags":["diagnostic","biologie","urgence"],"difficulty":2,"prompt":"Une femme de 40 ans en post-partum présente une douleur basithoracique associée à une dyspnée. Décrivez la stratégie diagnostique de l'embolie pulmonaire chez cette patiente, en fonction du risque hémodynamique et de la probabilité clinique.","rubric":[{"point":"Identifier le terrain à risque (post-partum) et la présentation évocatrice (douleur basithoracique, dyspnée, radiographie souvent normale)","weight":2},{"point":"Rechercher en premier lieu une hypotension ou un choc définissant le haut risque (PAS < 90 mmHg ou chute > 40 mmHg pendant plus de 15 minutes)","weight":2},{"point":"En cas de haut risque : scanner thoracique en urgence si disponible immédiatement, sinon échocardiographie à la recherche d'une dilatation du VD","weight":2},{"point":"En l'absence de choc, estimer la probabilité clinique par le score de Wells ou de Genève modifié","weight":1},{"point":"Probabilité faible ou modérée : doser les D-dimères ; positifs → angioscanner ; négatifs en Elisa → diagnostic éliminé","weight":2},{"point":"Probabilité forte : D-dimères inutiles, angioscanner d'emblée ; traitement antithrombotique débuté avant confirmation si probabilité intermédiaire ou haute","weight":1}],"model":"### Présentation évocatrice\nLe post-partum est un terrain classique d'embolie pulmonaire. La douleur basithoracique associée à la dyspnée, avec une radiographie thoracique souvent normale, doit faire évoquer le diagnostic.\n\n### Stratification du risque\nOn recherche en premier lieu une hypotension (PAS < 90 mmHg ou chute > 40 mmHg pendant plus de 15 minutes) ou un état de choc, définissant le haut risque.\n\n### En cas de haut risque\nUn scanner thoracique est réalisé en urgence s'il est immédiatement disponible ; à défaut, une échocardiographie recherche une dilatation du ventricule droit.\n\n### En l'absence de choc\nLa probabilité clinique est estimée par le score de Wells modifié ou de Genève modifié. Si elle est faible ou modérée, les D-dimères sont dosés : positifs, ils conduisent à un angioscanner thoracique ; négatifs en méthode Elisa, ils permettent d'éliminer le diagnostic. Si la probabilité est forte, les D-dimères sont inutiles et l'angioscanner est demandé d'emblée. En probabilité intermédiaire ou haute, un traitement antithrombotique est débuté avant même la confirmation diagnostique.","src":"p. 156-157"}],"edn":[{"id":"230-kfp-01","type":"KFP","rank":"A","objective":"230-obj-06","difficulty":2,"scenario":"Un homme de 58 ans, hypertendu et fumeur, consulte pour une douleur rétrosternale constrictive apparue au repos il y a 45 minutes, irradiant vers le bras gauche, avec sueurs profuses. L'examen retrouve une fréquence cardiaque à 92/min et une pression artérielle à 145/88 mmHg, sans signe de détresse vitale.","questions":[{"stem":"Quels examens complémentaires demandez-vous en urgence, avant tout autre geste ?","max":3,"options":["ECG 12 dérivations complété de V3R, V4R, V7, V8, V9","Radiographie pulmonaire","Dosage de la troponine ultrasensible","Angioscanner thoracique systématique","Dosage des D-dimères systématique","Échographie abdominale","Scanner cérébral","Épreuve d'effort immédiate","Gaz du sang systématique","Ponction pleurale"],"correct":[0,1,2],"explanation":"Devant toute suspicion des quatre urgences cardiovasculaires, ECG, radiographie pulmonaire et troponine ultrasensible sont systématiques, quelle que soit l'orientation clinique."},{"stem":"L'ECG montre un sus-décalage persistant du segment ST en antéro-septal. Quelle est la conduite à tenir immédiate ?","max":1,"options":["Attendre le résultat de la troponine avant toute décision","Transfert médicalisé direct vers la coronarographie ou l'Usic, via le 15","Hospitalisation en médecine polyvalente pour surveillance","Réalisation d'un scanner coronaire avant la coronarographie","Épreuve d'effort de contrôle dans les 48 heures","Retour à domicile avec traitement antalgique","Échographie transœsophagienne première","Surveillance simple aux urgences","Scanner thoracique injecté en urgence","IRM cardiaque de première intention"],"correct":[1],"explanation":"Un SCA avec sus-décalage persistant du segment ST impose un transfert médicalisé direct vers la coronarographie ou l'Usic, via le 15, sans attendre la troponine, en raison du risque de fibrillation ventriculaire."},{"stem":"Quelle est la place du dosage de la troponine ultrasensible dans cette situation précise ?","max":1,"options":["Il est indispensable pour poser le diagnostic","Il est inutile à la décision et ne doit jamais retarder la reperfusion","Il doit être répété toutes les 30 minutes avant la coronarographie","Il permet de choisir entre angioplastie et thrombolyse","Il élimine une dissection aortique associée","Il conditionne la dose d'anticoagulant","Il remplace l'ECG dans la décision de transfert","Il permet de dater précisément le début de la nécrose","Il est demandé uniquement en cas de doute diagnostique","Il n'est jamais réalisé dans le SCA ST+"],"correct":[1],"explanation":"Le SCA avec sus-décalage persistant du segment ST étant confirmé par l'ECG, le dosage de la troponine est inutile à la décision et ne doit jamais retarder la reperfusion par angioplastie ou thrombolyse."}],"src":"p. 153-155"},{"id":"230-kfp-02","type":"KFP","rank":"B","objective":"230-obj-06","difficulty":3,"scenario":"Une femme de 62 ans, hypertendue ancienne, présente une douleur thoracique brutale à type de déchirement, irradiant dans le dos, apparue au repos, avec un épisode de syncope. L'examen retrouve une asymétrie tensionnelle de 35 mmHg entre les deux bras et l'abolition du pouls radial droit.","questions":[{"stem":"Quels signes cliniques recherchez-vous pour étayer le diagnostic de dissection aortique ?","max":3,"options":["Asymétrie tensionnelle entre les deux bras","Abolition d'un pouls périphérique","Souffle d'insuffisance aortique","Turgescence jugulaire isolée","Frottement péricardique fugace","Hyperclarté à l'auscultation pulmonaire","Matité déclive d'un hémithorax","Signe de Homans","Souffle systolique éjectionnel au foyer pulmonaire","Reflux hépatojugulaire isolé"],"correct":[0,1,2],"explanation":"L'asymétrie tensionnelle, l'abolition d'un pouls et un souffle d'insuffisance aortique font partie des signes cliniques évocateurs de dissection aortique, selon le siège de la dissection."},{"stem":"Quels éléments composent le score de probabilité clinique de dissection aortique chez cette patiente ?","max":3,"options":["Terrain évocateur (Marfan, antécédent familial, anévrisme aortique connu)","Douleur brutale, intense, en déchirement","Signes évocateurs à l'examen clinique (pouls aboli, asymétrie tensionnelle, déficit neuro, IA, choc)","Antécédent personnel de fibrillation atriale","Présence d'une hyperthyroïdie associée","Élévation isolée de la CRP","Notion de tabagisme actif","Antécédent de reflux gastro-œsophagien","Présence d'une anémie chronique","Contexte de contage viral récent"],"correct":[0,1,2],"explanation":"Le score de probabilité clinique de dissection aortique comporte trois catégories cotées 1 point chacune : terrain évocateur, douleur évocatrice et signes évocateurs à l'examen clinique."},{"stem":"Chez cette patiente hémodynamiquement stable, quelle stratégie d'imagerie est adaptée à faible probabilité clinique (score 0-1) ?","max":1,"options":["Échocardiographie complétée par radiographie thoracique et dosage des D-dimères","Coronarographie immédiate sans imagerie préalable","IRM cardiaque en première intention","Scintigraphie pulmonaire de ventilation-perfusion","Aucune imagerie n'est nécessaire","Échographie abdominale seule","Radiographie thoracique seule, sans autre examen","Scanner cérébral systématique","Doppler des membres inférieurs isolé","Épreuve d'effort"],"correct":[0],"explanation":"Chez un patient stable à faible probabilité clinique de dissection aortique, l'échocardiographie est complétée par la radiographie thoracique et le dosage des D-dimères."}],"src":"p. 155-156"},{"id":"230-kfp-03","type":"KFP","rank":"A","objective":"230-obj-09","difficulty":2,"scenario":"Une femme de 45 ans, en période postopératoire d'une chirurgie orthopédique, présente une douleur basithoracique associée à une dyspnée aiguë. La pression artérielle est à 118/76 mmHg, sans signe de choc. La radiographie thoracique est normale.","questions":[{"stem":"En l'absence de choc, comment estimez-vous la probabilité clinique d'embolie pulmonaire ?","max":1,"options":["Par le score de Wells modifié ou de Genève modifié","Par un dosage isolé de la CRP","Par la seule auscultation cardiaque","Par une épreuve d'effort","Par un dosage isolé de la créatininémie","Par une simple évaluation de la fréquence cardiaque","Par un ECG seul","Par la radiographie thoracique seule","Par un dosage des enzymes hépatiques","Par une gazométrie artérielle isolée"],"correct":[0],"explanation":"En l'absence d'hypotension ou de choc, la probabilité clinique d'embolie pulmonaire est estimée par le score de Wells modifié ou de Genève modifié."},{"stem":"La probabilité clinique est jugée faible à modérée. Quelle est la première étape paraclinique ?","max":1,"options":["Doser les D-dimères","Réaliser un angioscanner thoracique d'emblée","Débuter un traitement antithrombotique sans autre examen","Réaliser une scintigraphie pulmonaire d'emblée","Réaliser une échocardiographie transœsophagienne","Demander un scanner cérébral","Réaliser une ponction pleurale","Prescrire une épreuve d'effort","Réaliser un cathétérisme cardiaque droit","Ne réaliser aucun examen complémentaire"],"correct":[0],"explanation":"En cas de probabilité clinique faible ou modérée, les D-dimères doivent être dosés avant d'envisager un angioscanner thoracique."},{"stem":"Les D-dimères reviennent à 1200 µg/L. Quelle est l'étape suivante ?","max":1,"options":["Angioscanner thoracique pour confirmer le diagnostic","Aucun examen supplémentaire n'est nécessaire","Nouveau dosage des D-dimères à 24 heures","Scintigraphie pulmonaire seulement","Retour à domicile avec surveillance simple","Épreuve d'effort de contrôle","IRM thoracique en première intention","Dosage répété de la troponine seul","Radiographie thoracique de contrôle seule","Échocardiographie transthoracique seule"],"correct":[0],"explanation":"Des D-dimères positifs (supérieurs à 500 µg/L) imposent la réalisation d'un angioscanner thoracique pour confirmer le diagnostic d'embolie pulmonaire."}],"src":"p. 156-157"},{"id":"230-tcs-01","type":"TCS","rank":"A","objective":"230-obj-07","difficulty":2,"vignette":"Un homme de 55 ans, aux facteurs de risque cardiovasculaire multiples, présente une douleur thoracique aiguë. Vous envisagez successivement plusieurs hypothèses diagnostiques face aux nouveaux éléments recueillis.","items":[{"hypothesis":"Si vous pensiez à un syndrome coronarien aigu","newInfo":"et que vous constatez un ECG strictement normal en pleine douleur","panel":[1,2,9,2,1],"explanation":"Un ECG percritique normal n'élimine pas le diagnostic de syndrome coronarien aigu : la probabilité reste globalement inchangée et doit rester surveillée."},{"hypothesis":"Si vous pensiez à une dissection aortique","newInfo":"et que vous constatez une asymétrie tensionnelle de 30 mmHg entre les deux bras","panel":[0,1,2,4,8],"explanation":"Une asymétrie tensionnelle marquée fait partie des signes cliniques évocateurs de dissection aortique et augmente fortement sa probabilité."},{"hypothesis":"Si vous pensiez à une embolie pulmonaire","newInfo":"et que la radiographie thoracique se révèle strictement normale","panel":[0,1,2,4,8],"explanation":"L'association d'une douleur, d'une dyspnée et d'une radiographie thoracique normale doit faire évoquer obligatoirement une embolie pulmonaire."},{"hypothesis":"Si vous pensiez à une péricardite aiguë","newInfo":"et que la douleur se trouve nettement calmée par l'antéflexion du buste","panel":[0,1,2,4,8],"explanation":"Une douleur calmée par l'antéflexion du buste est un caractère positionnel typique de la péricardite aiguë, augmentant fortement sa probabilité."}],"src":"p. 154-157"},{"id":"230-tcs-02","type":"TCS","rank":"B","objective":"230-obj-11","difficulty":3,"vignette":"Un patient hypertendu ancien présente une douleur thoracique brutale en déchirement. Le bilan initial progresse et de nouveaux éléments modifient vos hypothèses diagnostiques.","items":[{"hypothesis":"Si vous pensiez à une dissection aortique","newInfo":"et que vous percevez un souffle diastolique d'insuffisance aortique à l'auscultation","panel":[0,1,2,4,8],"explanation":"Un souffle d'insuffisance aortique fait partie des signes cliniques évocateurs de dissection aortique et renforce fortement cette hypothèse."},{"hypothesis":"Si vous pensiez à une dissection aortique étendue à une artère coronaire","newInfo":"et que l'ECG montre un sus-décalage du segment ST en territoire inférieur","panel":[0,2,3,7,3],"explanation":"L'ECG peut révéler un tableau de syndrome coronarien aigu si la dissection s'étend à une artère coronaire ; cet élément renforce modérément l'hypothèse sans la confirmer formellement."},{"hypothesis":"Si vous jugiez la probabilité clinique de dissection forte (score de 2 à 3)","newInfo":"et que le patient a un antécédent personnel de syndrome de Marfan associé à une douleur thoracique brutale en déchirement","panel":[0,1,1,4,9],"explanation":"Le terrain évocateur (Marfan) et la douleur évocatrice comptent chacun pour 1 point du score de probabilité clinique, portant le score à 2, soit une probabilité forte."},{"hypothesis":"Si vous pensiez qu'une chirurgie en urgence était indiquée","newInfo":"et que le scanner montre une dissection limitée à l'aorte descendante, sans complication périphérique","panel":[8,4,2,1,0],"explanation":"Une dissection de type B non compliquée, limitée à l'aorte descendante, relève d'un traitement médical et non d'une chirurgie en urgence, ce qui diminue fortement cette hypothèse."}],"src":"p. 155-156"},{"id":"230-tcs-03","type":"TCS","rank":"A","objective":"230-obj-09","difficulty":2,"vignette":"Une patiente de 38 ans, alitée depuis une intervention chirurgicale récente, présente une douleur basithoracique avec dyspnée. Vous réévaluez la probabilité d'embolie pulmonaire au fil des données recueillies.","items":[{"hypothesis":"Si vous pensiez à une embolie pulmonaire à haut risque","newInfo":"et que la PAS est mesurée à 75 mmHg depuis 25 minutes, sans trouble du rythme ni hypovolémie associée","panel":[0,1,2,4,8],"explanation":"Une hypotension prolongée définit le haut risque de l'embolie pulmonaire et renforce fortement cette hypothèse."},{"hypothesis":"Si vous pensiez à une embolie pulmonaire","newInfo":"et que les D-dimères reviennent négatifs par méthode Elisa, alors que la probabilité clinique prétest était modérée","panel":[8,4,2,1,0],"explanation":"Des D-dimères négatifs par méthode Elisa permettent d'éliminer le diagnostic d'embolie pulmonaire, même en présence d'une probabilité prétest modérée."},{"hypothesis":"Si vous pensiez à une embolie pulmonaire","newInfo":"et que la radiographie thoracique se révèle strictement normale","panel":[0,1,2,4,8],"explanation":"L'association douleur, dyspnée et radiographie normale renforce fortement la probabilité d'embolie pulmonaire."}],"src":"p. 156-157"},{"id":"230-tcs-04","type":"TCS","rank":"A","objective":"230-obj-06","difficulty":2,"vignette":"Un homme jeune, dans un contexte de contage viral récent, présente une douleur thoracique évoluant depuis deux jours. Vous réévaluez vos hypothèses au fur et à mesure de l'examen.","items":[{"hypothesis":"Si vous pensiez à une tamponnade péricardique","newInfo":"et que vous constatez une turgescence jugulaire avec un pouls paradoxal correspondant à une chute de la PAS de 15 mmHg à l'inspiration","panel":[0,1,2,4,8],"explanation":"La turgescence jugulaire et un pouls paradoxal supérieur à 10 mmHg sont des signes typiques de tamponnade péricardique, renforçant fortement cette hypothèse."},{"hypothesis":"Si vous pensiez à une péricardite aiguë non compliquée","newInfo":"et que l'échocardiographie est strictement normale, sans épanchement visible","panel":[1,2,9,2,1],"explanation":"Une échocardiographie normale n'élimine pas une péricardite sèche : la probabilité reste globalement inchangée, mais l'examen doit être répété."},{"hypothesis":"Si vous pensiez à une myopéricardite","newInfo":"et que la troponine est élevée de façon prolongée alors que la coronarographie est normale","panel":[0,1,2,4,8],"explanation":"Une élévation prolongée de la troponine associée à une coronarographie normale est évocatrice de myopéricardite, renforçant fortement cette hypothèse."}],"src":"p. 157-158"}],"trees":[{"id":"230-tree-01","title":"Conduite initiale devant une douleur thoracique aiguë","rank":"A","objective":"230-obj-02","intro":"Toute douleur thoracique aiguë impose une démarche en deux temps : écarter d'abord une menace vitale immédiate, puis rechercher systématiquement l'une des quatre urgences cardiovasculaires.","root":"n1","nodes":{"n1":{"type":"question","text":"Détresse vitale (respiratoire, hémodynamique ou neurologique) ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"n3"}],"note":"Détresse respiratoire : polypnée > 30/min, bradypnée < 10/min, SpO2 < 90 %. Détresse hémodynamique : choc, arrêt circulatoire, pouls paradoxal."},"n2":{"type":"action","text":"Prise en charge immédiate en réanimation ou USIC, avant toute caractérisation fine de la douleur","to":"n3"},"n3":{"type":"question","text":"Le tableau évoque-t-il l'une des 4 urgences cardiovasculaires (moyen mnémotechnique PIED) ?","options":[{"label":"Oui","to":"n4"},{"label":"Non","to":"n9"}],"note":"PIED : Péricardite, Infarctus (SCA), Embolie pulmonaire, Dissection aortique. Penser aussi à la rupture œsophagienne exceptionnelle."},"n4":{"type":"action","text":"Réaliser en urgence : ECG 12 dérivations + V3R, V4R, V7, V8, V9 ; radiographie pulmonaire ; troponine ultrasensible","to":"n5"},"n5":{"type":"question","text":"Sus-décalage persistant du segment ST (ou équivalent : BBG nouveau) à l'ECG ?","options":[{"label":"Oui","to":"n6"},{"label":"Non","to":"n7"}]},"n6":{"type":"end","tone":"danger","text":"SCA avec sus-ST : transfert médicalisé (appel du 15) direct vers la coronarographie ou l'USIC, sans attendre la troponine","note":"Ne pas recourir au 15 devant ce tableau est considéré comme une faute grave, en raison du risque de fibrillation ventriculaire."},"n7":{"type":"end","tone":"info","text":"Poursuivre la démarche ciblée selon l'orientation clinique : dissection aortique, embolie pulmonaire ou péricardite"},"n9":{"type":"end","tone":"ok","text":"Rechercher une cause extracardiaque, thoracique ou abdominale projetée, sans oublier les 6 urgences non cardiaques"}},"src":"p. 151-153"},{"id":"230-tree-02","title":"Démarche diagnostique du syndrome coronarien aigu","rank":"A","objective":"230-obj-07","intro":"Une fois le SCA évoqué, l'ECG conditionne la prise en charge immédiate ; la troponine ultrasensible n'intervient que pour les formes sans sus-décalage persistant.","root":"n1","nodes":{"n1":{"type":"question","text":"Sus-décalage persistant du ST, ou bloc de branche gauche nouveau ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"n3"}]},"n2":{"type":"end","tone":"danger","text":"SCA ST+ : reperfusion immédiate (angioplastie ou thrombolyse), sans attendre la troponine"},"n3":{"type":"question","text":"Sous-décalage isolé de V2 à V4, ou territoire circonflexe électriquement muet (penser V7-V8-V9) ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"n4"}],"note":"Une occlusion circonflexe peut se traduire uniquement par un sous-ST de V2 à V4 : à traiter comme un SCA ST+."},"n4":{"type":"action","text":"Doser la troponine ultrasensible à H0 puis la répéter à H1-H2","to":"n5"},"n5":{"type":"question","text":"Taux initial élevé, ou augmentation significative entre H0 et H1-H2 ?","options":[{"label":"Oui","to":"n6"},{"label":"Non","to":"n7"}]},"n6":{"type":"end","tone":"warn","text":"SCA sans sus-ST à haut risque : prise en charge en USIC"},"n7":{"type":"end","tone":"info","text":"Évoquer un diagnostic différentiel ou un SCA à bas risque ; poursuivre la surveillance en USIC"}},"src":"p. 154-155"},{"id":"230-tree-03","title":"Dissection aortique : probabilité clinique et imagerie","rank":"B","objective":"230-obj-11","intro":"Le score de probabilité clinique et la stabilité hémodynamique orientent le choix entre échocardiographie et angioscanner thoracique.","root":"n1","nodes":{"n1":{"type":"question","text":"Douleur évocatrice (déchirement, migratrice, dorsale) sur terrain à risque (HTA ancienne, Marfan) ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"n8"}]},"n2":{"type":"action","text":"Calculer le score de probabilité clinique (terrain, douleur, examen : 1 point chacun, sur 3)","to":"n3"},"n3":{"type":"question","text":"Patient hémodynamiquement stable ?","options":[{"label":"Oui","to":"n4"},{"label":"Non","to":"n7"}]},"n4":{"type":"question","text":"Score de probabilité faible (0-1) ?","options":[{"label":"Oui","to":"n5"},{"label":"Non","to":"n6"}]},"n5":{"type":"action","text":"Compléter l'échocardiographie par la radiographie thoracique (élargissement médiastinal) et le dosage des D-dimères","to":"n9"},"n6":{"type":"end","tone":"warn","text":"Probabilité forte (score 2-3) : ETT complétée d'une ETO, ou angioscanner thoracique, pour le diagnostic positif et la planification chirurgicale"},"n7":{"type":"end","tone":"danger","text":"Patient instable : échocardiographie au lit du malade ; chirurgie en urgence si atteinte de l'aorte ascendante (type A)"},"n8":{"type":"end","tone":"ok","text":"Présentation peu évocatrice : envisager un autre diagnostic parmi les urgences cardiovasculaires"},"n9":{"type":"end","tone":"info","text":"D-dimères normaux et radiographie non évocatrice : diagnostic rendu peu probable (D-dimères normaux rares en cas de dissection)"}},"src":"p. 155-156"},{"id":"230-tree-04","title":"Embolie pulmonaire : stratification du risque et confirmation diagnostique","rank":"A","objective":"230-obj-09","intro":"La présence d'un choc ou d'une hypotension définit d'emblée le haut risque ; en son absence, la probabilité clinique guide la place des D-dimères.","root":"n1","nodes":{"n1":{"type":"question","text":"Hypotension (PAS < 90 mmHg ou chute > 40 mmHg pendant plus de 15 minutes) ou état de choc ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"n3"}]},"n2":{"type":"end","tone":"danger","text":"EP à haut risque : scanner thoracique en urgence si disponible immédiatement, sinon échocardiographie (recherche de dilatation du VD)"},"n3":{"type":"action","text":"Estimer la probabilité clinique par le score de Wells modifié ou de Genève modifié","to":"n4"},"n4":{"type":"question","text":"Probabilité clinique forte ?","options":[{"label":"Oui","to":"n5"},{"label":"Non","to":"n6"}]},"n5":{"type":"end","tone":"warn","text":"D-dimères inutiles : angioscanner thoracique demandé d'emblée pour confirmer le diagnostic"},"n6":{"type":"action","text":"Probabilité faible ou modérée : doser les D-dimères (méthode Elisa)","to":"n7"},"n7":{"type":"question","text":"D-dimères positifs (> 500 µg/L, ou > 10 × l'âge après 50 ans) ?","options":[{"label":"Oui","to":"n8"},{"label":"Non","to":"n9"}]},"n8":{"type":"end","tone":"warn","text":"Angioscanner thoracique demandé pour confirmer le diagnostic","note":"En cas de probabilité intermédiaire ou haute, débuter le traitement antithrombotique avant même la confirmation."},"n9":{"type":"end","tone":"ok","text":"D-dimères négatifs : diagnostic d'embolie pulmonaire éliminé, même si la probabilité prétest était modérée"}},"src":"p. 156-157"},{"id":"230-tree-05","title":"Douleur thoracique positionnelle : péricardite ou tamponnade ?","rank":"A","objective":"230-obj-04","intro":"La péricardite non compliquée est la plus bénigne des quatre urgences, mais la tamponnade qui peut la compliquer est, elle, une urgence vitale.","root":"n1","nodes":{"n1":{"type":"question","text":"Douleur augmentée en décubitus/inspiration, calmée par l'antéflexion, sur contexte viral ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"n10"}]},"n2":{"type":"action","text":"ECG, échocardiographie et dosage des troponines","to":"n3"},"n3":{"type":"question","text":"Signes droits, choc ou pouls paradoxal (chute PAS inspiratoire > 10 mmHg) ?","options":[{"label":"Oui","to":"n4"},{"label":"Non","to":"n5"}]},"n4":{"type":"end","tone":"danger","text":"Tamponnade péricardique : urgence vitale, à l'inverse de la péricardite non compliquée"},"n5":{"type":"question","text":"Élévation prolongée de la troponine avec trouble cinétique segmentaire ou diffus du VG ?","options":[{"label":"Oui","to":"n6"},{"label":"Non","to":"n7"}]},"n6":{"type":"end","tone":"warn","text":"Myopéricardite : peut mimer un SCA, mais coronarographie normale attendue ; l'IRM aide au diagnostic différentiel"},"n7":{"type":"end","tone":"ok","text":"Péricardite aiguë non compliquée : diagnostic d'élimination, le plus bénin des 4 urgences","note":"Une échocardiographie normale n'élimine pas une péricardite sèche : il faut savoir la répéter."},"n10":{"type":"end","tone":"info","text":"Caractère de la douleur peu évocateur d'une péricardite : orienter vers les autres urgences cardiovasculaires"}},"src":"p. 157-158"},{"id":"230-tree-06","title":"Douleur thoracique chronique : probabilité clinique de coronaropathie","rank":"A","objective":"230-obj-12","intro":"Un score combinant les caractéristiques de la douleur ou de la dyspnée et le nombre de facteurs de risque cardiovasculaire guide le choix de l'examen complémentaire.","root":"n1","nodes":{"n1":{"type":"action","text":"Calculer la probabilité clinique : douleur/dyspnée (0 à 3 points) + facteurs de risque cardiovasculaire (0 à 5 points)","to":"n2"},"n2":{"type":"question","text":"Quelle est la probabilité clinique obtenue ?","options":[{"label":"< 5 %","to":"n3"},{"label":"5-15 %","to":"n4"},{"label":"≥ 15 %","to":"n8"}]},"n3":{"type":"end","tone":"ok","text":"Très faible probabilité : aucun examen complémentaire nécessaire"},"n4":{"type":"end","tone":"warn","text":"Zone grise : scanner coronarien d'emblée, ou réévaluation par ECG de repos, épreuve d'effort, échocardiographie, score calcique ou doppler vasculaire"},"n8":{"type":"question","text":"Précisez le niveau de probabilité clinique","options":[{"label":"15-50 %","to":"n5"},{"label":"> 50-85 %","to":"n7"},{"label":"> 85 %","to":"n6"}]},"n5":{"type":"end","tone":"info","text":"Probabilité modérée : scanner coronarien ou imagerie fonctionnelle (scintigraphie, échographie ou IRM de stress), selon l'expérience du centre"},"n6":{"type":"end","tone":"danger","text":"Très forte probabilité : coronarographie à titre diagnostique"},"n7":{"type":"end","tone":"info","text":"Probabilité élevée : imagerie fonctionnelle (scintigraphie, échographie ou IRM de stress)"}},"src":"p. 159"}],"treatments":{"data":[{"id":"230-tx-01","rank":"A","class":"Reperfusion coronarienne en urgence (angioplastie primaire ou thrombolyse)","molecules":[],"context":"SCA avec sus-décalage persistant du segment ST, ou équivalent électrique (BBG nouveau, sous-ST de V2 à V4 évocateur d'une occlusion circonflexe)","indications":["SCA ST+ confirmé à l'ECG","Bloc de branche gauche considéré comme nouveau, assimilé à un équivalent de SCA ST+","Sous-décalage de V2 à V4 avec douleur thoracique prolongée, évocateur d'une occlusion de l'artère circonflexe"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Le dosage de la troponine ne doit jamais retarder la reperfusion.","Le transfert doit être médicalisé (appel du 15), en raison du risque de fibrillation ventriculaire pendant le transport."],"src":"p. 153-155"},{"id":"230-tx-02","rank":"A","class":"Traitement antithrombotique probabiliste de l'embolie pulmonaire","molecules":[],"context":"Embolie pulmonaire à probabilité clinique intermédiaire ou haute, avant même la confirmation diagnostique par imagerie","indications":["Probabilité clinique intermédiaire ou haute d'embolie pulmonaire, dans l'attente de la confirmation par angioscanner ou échocardiographie"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Ne pas attendre la confirmation diagnostique pour débuter le traitement lorsque la probabilité clinique est intermédiaire ou haute."],"src":"p. 157"},{"id":"230-tx-03","rank":"B","class":"Chirurgie de la dissection aortique","molecules":[],"context":"Dissection aortique avec atteinte de l'aorte ascendante (type A de Stanford, types I et II de De Bakey)","indications":["Atteinte de l'aorte ascendante : dissection de type A de Stanford, ou types I et II de De Bakey"],"contraindications":["Forme limitée à l'aorte descendante (type B) non compliquée : traitement médical préféré à la chirurgie"],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["L'angioscanner thoracique aide à planifier le geste chirurgical : porte d'entrée, extension, atteinte des artères carotidiennes, mésentériques ou rénales."],"src":"p. 156"},{"id":"230-tx-04","rank":"A","class":"Normalisation de la pression artérielle dans la dissection aortique","molecules":[],"context":"Toute dissection aortique, quel que soit son type : il s'agit d'une urgence hypertensive","indications":["Dissection aortique, quel que soit le siège de l'atteinte"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["La pression artérielle doit être normalisée en urgence : ne jamais la tolérer au prétexte d'assurer une perfusion d'organe."],"src":"p. 156"},{"id":"230-tx-05","rank":"A","class":"Trinitrine en spray (dérivé nitré)","molecules":["Trinitrine"],"context":"Angor stable typique, à visée diagnostique (test thérapeutique) et symptomatique","indications":["Douleur angineuse d'effort typique, pour confirmer le diagnostic et soulager rapidement le patient"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["L'angor stable typique cède à l'arrêt de l'effort ou après trinitrine en 1 à 3 minutes.","Piège : le spasme œsophagien, douleur pseudo-angineuse déclenchée par la déglutition, peut lui aussi être calmé par les dérivés nitrés."],"src":"p. 158-160"},{"id":"230-tx-06","rank":"A","class":"Transfert médicalisé et orientation en urgence (SAMU-15, USIC, coronarographie)","molecules":[],"context":"Toute détresse vitale, ou toute suspicion de SCA avec sus-décalage persistant du ST, nécessitant un plateau technique spécialisé","indications":["SCA ST+ : transfert direct vers la salle de coronarographie ou l'USIC","Détresse vitale (respiratoire, hémodynamique ou neurologique) : transfert en réanimation ou en USIC"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Ne pas recourir au 15 devant un tableau évocateur de syndrome coronarien est considéré comme une faute grave.","Le risque principal pendant le transport est la fibrillation ventriculaire, ce qui justifie un transfert médicalisé."],"src":"p. 151-153"}],"strategies":[{"id":"230-strat-01","rank":"A","title":"Stratégie générale devant une douleur thoracique aiguë","content":"1. Rechercher une détresse vitale (respiratoire, hémodynamique, neurologique) et la traiter immédiatement le cas échéant, avant toute analyse fine de la douleur.\n2. Évoquer systématiquement les 4 urgences cardiovasculaires (moyen mnémotechnique PIED), sans oublier la rupture œsophagienne exceptionnelle.\n3. Prescrire en urgence : ECG 12 dérivations + V3R, V4R, V7, V8, V9 ; radiographie pulmonaire ; troponine ultrasensible.\n4. Si sus-décalage persistant du ST : transfert médicalisé (appel du 15) direct vers la coronarographie ou l'USIC, sans attendre la troponine.\n5. Sinon, orienter la démarche selon le terrain, les caractéristiques de la douleur et l'examen clinique vers la dissection aortique, l'embolie pulmonaire ou la péricardite.\n6. En l'absence d'argument pour les 4 urgences, rechercher une cause extracardiaque, en particulier l'une des 6 urgences non cardiaques.","src":"p. 151-153"},{"id":"230-strat-02","rank":"A","title":"Stratégie diagnostique du SCA sans sus-décalage persistant du ST","content":"1. Doser la troponine ultrasensible dès l'admission (H0).\n2. Répéter le dosage 1 à 2 heures plus tard (H1-H2) : le délai précis dépend de la méthode utilisée.\n3. Si le taux à H0 est très faible ou faible, sans augmentation significative au 2e dosage : évoquer un diagnostic différentiel ou un SCA à bas risque, et poursuivre la surveillance en USIC.\n4. Si le taux à H0 est élevé, ou faible mais avec une augmentation significative au 2e dosage : retenir le diagnostic de SCA sans sus-ST à haut risque.\n5. Ne jamais attendre le résultat de la troponine pour traiter un SCA avec sus-décalage persistant du ST : cette règle ne s'applique qu'aux formes sans sus-ST.","src":"p. 154-155"},{"id":"230-strat-03","rank":"B","title":"Stratégie diagnostique et thérapeutique de la dissection aortique","content":"1. Estimer la probabilité clinique par un score reposant sur le terrain, la douleur et l'examen clinique (1 point chacun, sur 3).\n2. Chez le patient stable à faible probabilité (score 0-1) : compléter l'échocardiographie par la radiographie thoracique et les D-dimères.\n3. Chez le patient stable à forte probabilité (score 2-3), ou en cas de doute : angioscanner thoracique, ou ETT complétée d'une ETO si l'état hémodynamique le permet.\n4. Chez le patient instable : échocardiographie réalisée sans délai.\n5. Normaliser la pression artérielle en urgence, quelle que soit la situation (urgence hypertensive).\n6. Orienter vers la chirurgie en urgence si l'aorte ascendante est atteinte (type A) ; traitement médical pour les formes limitées à l'aorte descendante (type B) non compliquées.","src":"p. 155-156"},{"id":"230-strat-04","rank":"A","title":"Stratégie diagnostique de l'embolie pulmonaire selon le niveau de risque","content":"1. Rechercher une hypotension (PAS < 90 mmHg ou chute > 40 mmHg pendant plus de 15 minutes) ou un état de choc, définissant le haut risque.\n2. En cas de haut risque : scanner thoracique en urgence si disponible immédiatement, sinon échocardiographie à la recherche d'une dilatation du VD.\n3. En l'absence de choc : estimer la probabilité clinique par le score de Wells modifié ou de Genève modifié.\n4. Si la probabilité est faible ou modérée : doser les D-dimères ; s'ils sont positifs, demander un angioscanner thoracique ; s'ils sont négatifs (méthode Elisa), le diagnostic est éliminé.\n5. Si la probabilité est forte : les D-dimères sont inutiles, l'angioscanner thoracique est demandé d'emblée.\n6. En cas de probabilité intermédiaire ou haute, débuter le traitement antithrombotique avant même la confirmation diagnostique.","src":"p. 156-157"},{"id":"230-strat-05","rank":"A","title":"Démarche diagnostique devant une suspicion de syndrome coronarien chronique","content":"1. Calculer un score de probabilité clinique combinant les caractéristiques de la douleur thoracique ou de la dyspnée (0 à 3 points) et le nombre de facteurs de risque cardiovasculaire (0 à 5 points).\n2. Probabilité < 5 % : aucun examen complémentaire n'est nécessaire.\n3. Probabilité 5-15 % (zone grise) : scanner coronarien d'emblée, ou réévaluation à l'aide d'examens complémentaires (ECG de repos, épreuve d'effort, échocardiographie, score calcique, doppler vasculaire).\n4. Probabilité 15-50 % : scanner coronarien ou imagerie fonctionnelle (scintigraphie, échographie ou IRM de stress), selon l'expérience du centre.\n5. Probabilité > 50-85 % : imagerie fonctionnelle (scintigraphie, échographie ou IRM de stress).\n6. Probabilité > 85 % : coronarographie à titre diagnostique d'emblée.","src":"p. 159"}]},"cases":[{"id":"230-case-01","title":"M. Lefort, 54 ans, douleur thoracique brutale au repos","rank":"A","summary":"Tabagique et hypertendu, il présente une douleur thoracique de repos sans sus-décalage persistant du ST ; la cinétique de la troponine oriente la décision.","difficulty":2,"timeline":["Appel et évaluation initiale","Examen clinique ciblé","ECG et orientation immédiate","Biologie et cinétique de la troponine","Décision thérapeutique","Piège diagnostique et réévaluation","Synthèse"],"steps":[{"id":"230-case-01-s01","phase":0,"narrative":"M. Lefort, 54 ans, tabagique et hypertendu, appelle car il présente depuis 40 minutes une douleur thoracique constrictive apparue au repos. À l'arrivée, il est conscient, orienté, sans plainte respiratoire majeure.","question":{"type":"QRM","stem":"Quels éléments, s'ils étaient présents chez M. Lefort, témoigneraient d'une détresse vitale imposant une prise en charge immédiate ?","options":[{"t":"Une fréquence respiratoire à 34/min","ok":true,"why":"Une polypnée > 30/min signe une détresse respiratoire."},{"t":"Une cyanose des extrémités avec désaturation à 86 %","ok":true,"why":"Cyanose et SpO2 < 90 % sont des critères de détresse respiratoire."},{"t":"Une douleur cotée à 9/10 sur l'échelle numérique","ok":false,"why":"L'intensité de la douleur seule n'est pas un critère de détresse vitale."},{"t":"Des marbrures des genoux avec oligurie","ok":true,"why":"Elles témoignent d'un état de choc avec hypoperfusion périphérique."},{"t":"Un souffle systolique au foyer aortique déjà connu","ok":false,"why":"Un souffle ancien et connu n'est pas en lui-même un signe de détresse vitale."}],"explanation":"La recherche d'une détresse vitale prime sur l'analyse fine de la douleur et repose sur des critères respiratoires, hémodynamiques et neurologiques précis."},"reveal":"M. Lefort ne présente aucun de ces signes : fréquence respiratoire à 18/min, SpO2 à 97 %, pas de marbrures. L'équipe poursuit la caractérisation de la douleur.","src":"p. 151"},{"id":"230-case-01-s02","phase":0,"narrative":"La douleur, apparue au repos, persiste et le patient précise qu'elle dure maintenant depuis plus de 40 minutes.","question":{"type":"QROC","question":"Au-delà de quelle durée une douleur thoracique de repos doit-elle faire évoquer un infarctus du myocarde ?","answer":"20 minutes","accept":["20 min","vingt minutes"],"keywords":["20","minutes"],"explanation":"L'infarctus est à évoquer dès que la douleur dépasse 20 minutes."},"reveal":"La durée de la douleur oriente déjà fortement vers un syndrome coronarien aigu ; l'équipe engage la démarche diagnostique correspondante.","src":"p. 154"},{"id":"230-case-01-s03","phase":1,"narrative":"L'examen clinique est réalisé pendant que la douleur persiste.","question":{"type":"QRM","stem":"Quels éléments de l'examen clinique recherchez-vous en priorité pour orienter vers un syndrome coronarien aigu plutôt qu'une autre urgence cardiovasculaire ?","options":[{"t":"Un souffle carotidien ou fémoral témoignant d'une autre localisation de l'athérosclérose","ok":true,"why":"Le SCA s'inscrit souvent dans une maladie athéromateuse diffuse."},{"t":"L'abolition d'un pouls périphérique évocatrice d'athérosclérose","ok":true,"why":"Elle recherche une autre localisation de l'athérome, en dehors de toute complication."},{"t":"Un frottement péricardique","ok":false,"why":"C'est un signe de péricardite, non de syndrome coronarien aigu."},{"t":"Une asymétrie tensionnelle supérieure à 20 mmHg entre les deux bras","ok":false,"why":"Elle oriente vers une dissection aortique."},{"t":"Une matité pleurale de la base","ok":false,"why":"Elle évoque un épanchement pleural, non un SCA."}],"explanation":"L'examen clinique du SCA est le plus souvent normal en l'absence de complication ; il recherche surtout une autre localisation de l'athérosclérose."},"reveal":"L'examen est strictement normal, sans souffle vasculaire ni abolition de pouls. La démarche paraclinique est engagée.","src":"p. 154"},{"id":"230-case-01-s04","phase":2,"narrative":"L'équipe prescrit les examens complémentaires systématiques devant cette suspicion de syndrome coronarien aigu.","question":{"type":"QRM","stem":"Quels examens complémentaires sont systématiques devant cette douleur thoracique évocatrice de SCA ?","options":[{"t":"ECG 12 dérivations complété par V3R, V4R, V7, V8, V9","ok":true,"why":"Ces dérivations complémentaires permettent de ne pas méconnaître une ischémie postérieure ou du VD."},{"t":"Radiographie pulmonaire","ok":true,"why":"Elle est systématique devant toute suspicion des 4 urgences cardiovasculaires."},{"t":"Troponine ultrasensible","ok":true,"why":"Son dosage est systématique, même si son interprétation dépend du type de SCA."},{"t":"Dosage systématique des D-dimères","ok":false,"why":"Les D-dimères ne sont pas un examen systématique du SCA ; ils sont réservés à la suspicion d'embolie pulmonaire ou de dissection."},{"t":"Angioscanner thoracique d'emblée","ok":false,"why":"Ce n'est pas un examen systématique du SCA."}],"explanation":"ECG complet, radiographie pulmonaire et troponine ultrasensible sont systématiques devant toute suspicion des 4 urgences cardiovasculaires."},"reveal":"L'ECG est réalisé en urgence ; il retrouve un sous-décalage du segment ST de V2 à V4, sans sus-décalage.","src":"p. 153"},{"id":"230-case-01-s05","phase":2,"narrative":"Le sous-décalage isolé de V2 à V4 interpelle l'interne, qui se souvient d'un piège classique de ce territoire électrique.","question":{"type":"QRU","stem":"Quelle est la conduite immédiate la plus appropriée devant ce sous-décalage de V2 à V4 ?","options":[{"t":"Enregistrer les dérivations V7, V8, V9 à la recherche d'une ischémie circonflexe électriquement muette","ok":true,"why":"Un sous-ST de V2 à V4 peut traduire une occlusion circonflexe, à traiter comme un SCA ST+."},{"t":"Conclure à une péricardite devant ce tracé","ok":false,"why":"Le sous-décalage de PQ et le sus-ST concave diffus caractérisent la péricardite, pas ce tracé."},{"t":"Attendre le résultat de la troponine avant tout autre geste","ok":false,"why":"L'attente de la troponine ne doit jamais retarder la prise en charge d'un équivalent de SCA ST+."},{"t":"Demander d'emblée un angioscanner pulmonaire","ok":false,"why":"Rien n'oriente ici vers une embolie pulmonaire."},{"t":"Rassurer le patient et le renvoyer à domicile","ok":false,"why":"Une douleur prolongée avec ce type de sous-décalage impose une prise en charge urgente."}],"explanation":"Le sous-décalage de V2 à V4 associé à une douleur prolongée doit faire rechercher une occlusion circonflexe et être pris en charge comme un SCA ST+."},"reveal":"Les dérivations postérieures ne montrent pas de sus-décalage franc. Le diagnostic retenu est un SCA sans sus-décalage persistant du ST ; la troponine ultrasensible est dosée.","src":"p. 154"},{"id":"230-case-01-s06","phase":3,"narrative":"La troponine ultrasensible est dosée à H0, puis un second prélèvement est programmé.","question":{"type":"QROC","question":"À quel délai après le premier dosage la troponine ultrasensible doit-elle être répétée pour juger de sa cinétique ?","answer":"1 à 2 heures","accept":["H1-H2","1-2h","une à deux heures"],"keywords":["1","2","heures"],"explanation":"Le second dosage est réalisé 1 à 2 heures après le premier, le délai précis dépendant de la méthode utilisée."},"reveal":"Le dosage à H0 revient faible ; le second dosage est programmé.","src":"p. 155"},{"id":"230-case-01-s07","phase":3,"narrative":"Le second dosage de troponine, réalisé 1h30 plus tard, montre une augmentation significative par rapport au premier prélèvement.","question":{"type":"QRU","stem":"Comment interprétez-vous cette cinétique de troponine chez M. Lefort ?","options":[{"t":"Elle signe un syndrome coronarien aigu sans sus-ST à haut risque","ok":true,"why":"Une augmentation significative entre H0 et H1-H2 pose ce diagnostic."},{"t":"Elle permet d'éliminer un syndrome coronarien aigu","ok":false,"why":"C'est au contraire un argument fort en faveur du diagnostic."},{"t":"Elle signe un SCA à bas risque, à surveiller en ambulatoire","ok":false,"why":"Une cinétique significative définit au contraire un haut risque, non un bas risque."},{"t":"Elle impose de refaire uniquement un nouvel ECG, sans autre mesure","ok":false,"why":"La cinétique de troponine oriente directement la stratégie de prise en charge, au-delà du seul ECG."},{"t":"Elle nécessite d'attendre un troisième dosage à 6 heures avant toute décision","ok":false,"why":"Le livre ne prévoit qu'un dosage à H0 et un second à H1-H2 pour trancher."}],"explanation":"Un taux initial élevé, ou une augmentation significative au 2e dosage, pose le diagnostic de SCA sans sus-ST à haut risque."},"reveal":"Le diagnostic de SCA sans sus-décalage persistant du ST, à haut risque, est retenu.","src":"p. 155"},{"id":"230-case-01-s08","phase":4,"narrative":"Le diagnostic de SCA sans sus-ST à haut risque étant posé, l'équipe organise la suite de la prise en charge.","question":{"type":"QRM","stem":"Quelles mesures sont adaptées à ce stade pour M. Lefort ?","options":[{"t":"Transfert et surveillance rapprochée en USIC","ok":true,"why":"Un SCA sans sus-ST à haut risque relève d'une surveillance en unité de soins intensifs cardiologiques."},{"t":"Organiser une coronarographie","ok":true,"why":"La coronarographie occupe une place diagnostique et thérapeutique dans la prise en charge du SCA."},{"t":"Débuter une reperfusion par thrombolyse immédiate, comme pour un SCA ST+","ok":false,"why":"La reperfusion urgente sans délai concerne spécifiquement le SCA avec sus-décalage persistant du ST."},{"t":"Renvoyer le patient à domicile avec un contrôle à 1 semaine","ok":false,"why":"Un SCA à haut risque impose une prise en charge hospitalière immédiate."},{"t":"Différer toute exploration coronaire de plusieurs semaines","ok":false,"why":"Le haut risque impose au contraire une exploration rapide."}],"explanation":"Le SCA sans sus-ST à haut risque impose surveillance en USIC et exploration coronarographique, sans relever de la reperfusion en urgence propre au sus-ST."},"reveal":"M. Lefort est transféré en USIC ; une coronarographie est programmée dans les suites.","src":"p. 153-155"},{"id":"230-case-01-s09","phase":5,"narrative":"En relisant le dossier, l'interne s'interroge sur un ECG initial qui, chez un autre patient vu la veille avec une douleur similaire, était strictement normal en pleine douleur.","question":{"type":"QRM","stem":"Que retenez-vous de la valeur d'un ECG normal réalisé en pleine douleur thoracique ?","options":[{"t":"Un ECG normal per-critique n'élimine pas le diagnostic de SCA","ok":true,"why":"C'est un principe rappelé explicitement pour ne pas méconnaître un SCA."},{"t":"Il permet d'abandonner définitivement l'hypothèse de SCA","ok":false,"why":"C'est au contraire une erreur classique à éviter."},{"t":"Une ischémie de l'artère circonflexe peut être électriquement muette sur l'ECG standard","ok":true,"why":"D'où l'intérêt des dérivations V7, V8, V9."},{"t":"Il faut alors répéter la troponine à distance pour ne pas méconnaître le diagnostic","ok":true,"why":"La cinétique biologique complète l'ECG lorsque celui-ci est pris en défaut."},{"t":"Un bloc de branche gauche n'est un équivalent de SCA ST+ que s'il est ancien","ok":false,"why":"C'est l'inverse : c'est le caractère nouveau du BBG qui en fait un équivalent de SCA ST+."}],"explanation":"Un ECG per-critique normal n'élimine jamais un SCA ; le territoire circonflexe est une zone électriquement muette classique."},"reveal":"L'équipe retient la leçon : chez M. Lefort, la cinétique de troponine a permis de confirmer le diagnostic malgré un ECG initialement peu contributif dans le territoire postérieur.","src":"p. 154"},{"id":"230-case-01-s10","phase":5,"narrative":"Le senior insiste sur un point que tout interne doit connaître avant de conclure trop vite à un ECG normal ou rassurant.","question":{"type":"QROC","question":"Quel trouble de conduction, lorsqu'il est nouveau, doit être considéré comme un équivalent électrique de SCA avec sus-décalage persistant du ST ?","answer":"Le bloc de branche gauche (BBG) nouveau","accept":["BBG nouveau","bloc de branche gauche"],"keywords":["bloc","branche","gauche"],"explanation":"Un bloc de branche gauche nouveau doit être considéré comme un équivalent de SCA avec sus-décalage du segment ST."},"reveal":"Ce point est noté dans le dossier de M. Lefort pour la suite de sa surveillance.","src":"p. 154"},{"id":"230-case-01-s11","phase":6,"narrative":"Avant la sortie du service, l'équipe reprend le dossier pour synthétiser la prise en charge qui aurait été nécessaire si l'ECG initial avait montré un authentique sus-décalage persistant du ST.","question":{"type":"OPEN","prompt":"Résumez les grandes étapes de la prise en charge en urgence d'un patient présentant un SCA avec sus-décalage persistant du segment ST à l'ECG.","rubric":[{"point":"Transfert médicalisé, via l'appel du 15","weight":2},{"point":"Ne jamais attendre le résultat de la troponine pour agir","weight":2},{"point":"Reperfusion coronarienne par angioplastie ou thrombolyse débutée sans délai","weight":2},{"point":"Transfert direct vers la salle de coronarographie ou l'USIC","weight":1}],"model":"Devant un sus-décalage persistant du ST, il faut organiser sans délai un transfert médicalisé (appel du 15) direct vers la coronarographie ou l'USIC, en raison du risque de fibrillation ventriculaire. La troponine, inutile à la décision dans cette forme, ne doit jamais retarder la reperfusion : angioplastie ou thrombolyse doivent être débutées au plus vite."},"reveal":"L'équipe valide la synthèse : dans le cas réel de M. Lefort, l'absence de sus-ST persistant avait justifié la voie de la troponine plutôt que la reperfusion immédiate.","src":"p. 153-155"},{"id":"230-case-01-s12","phase":6,"narrative":"Un mois plus tard, M. Lefort revient en consultation de suivi après sa coronarographie.","question":{"type":"QRM","stem":"Concernant les quatre urgences cardiovasculaires à évoquer devant toute douleur thoracique aiguë, quelles affirmations sont exactes ?","options":[{"t":"Le moyen mnémotechnique PIED regroupe péricardite, infarctus, embolie pulmonaire et dissection","ok":true,"why":"C'est la définition même de ce moyen mnémotechnique."},{"t":"Ces quatre urgences doivent être évoquées systématiquement, après avoir écarté une détresse vitale","ok":true,"why":"C'est la seconde étape de la démarche générale."},{"t":"La rupture de l'œsophage ne fait jamais partie du diagnostic à évoquer dans ce contexte","ok":false,"why":"C'est une 5e cause exceptionnelle mais à garder en mémoire."},{"t":"ECG, radiographie pulmonaire et troponine ultrasensible sont systématiques devant ces 4 urgences","ok":true,"why":"Ce sont les examens complémentaires systématiques du chapitre."},{"t":"Seul le syndrome coronarien aigu justifie la réalisation d'un ECG en urgence","ok":false,"why":"L'ECG est systématique devant les 4 urgences, pas seulement le SCA."}],"explanation":"La démarche générale devant une douleur thoracique aiguë repose sur la recherche d'une détresse vitale puis des 4 urgences cardiovasculaires (PIED), avec un bilan systématique commun."},"reveal":"M. Lefort va bien ; le suivi cardiologique se poursuit selon les modalités habituelles.","src":"p. 153"}]},{"id":"230-case-02","title":"Mme Dubreuil, 45 ans, douleur basithoracique et dyspnée après une chirurgie du genou","rank":"A","summary":"Opérée du genou dix jours plus tôt, elle présente une douleur basithoracique brutale avec dyspnée ; la démarche différencie embolie pulmonaire, péricardite et dissection.","difficulty":2,"timeline":["Consultation initiale","Recherche de détresse vitale","Orientation vers les 4 urgences","Stratification du risque et probabilité clinique","Examens complémentaires ciblés","Diagnostic retenu et prise en charge","Suivi"],"steps":[{"id":"230-case-02-s01","phase":0,"narrative":"Mme Dubreuil, 45 ans, tabagique et sous contraception œstroprogestative, a été opérée du genou dix jours plus tôt avec un alitement prolongé. Elle consulte pour une douleur basithoracique droite brutale associée à une dyspnée, apparue il y a 3 heures.","question":{"type":"QRM","stem":"Quels éléments du terrain de Mme Dubreuil sont évocateurs d'une embolie pulmonaire ?","options":[{"t":"Chirurgie récente avec alitement prolongé","ok":true,"why":"La période postopératoire et l'alitement sont des terrains classiques de maladie thromboembolique."},{"t":"Contraception œstroprogestative associée au tabac","ok":true,"why":"C'est un facteur de risque explicitement cité de maladie thromboembolique."},{"t":"Antécédent de péricardite aiguë récidivante","ok":false,"why":"C'est un terrain évocateur de péricardite, non d'embolie pulmonaire."},{"t":"Contage viral récent","ok":false,"why":"C'est un terrain évocateur de péricardite, non d'embolie pulmonaire."},{"t":"Âge de 45 ans en lui-même","ok":false,"why":"L'âge seul n'est pas cité comme un facteur de risque déterminant ici."}],"explanation":"Le terrain de l'embolie pulmonaire associe classiquement chirurgie récente, alitement, contraception œstroprogestative et tabac, antécédents thromboemboliques ou néoplasie."},"reveal":"Le terrain oriente fortement vers une embolie pulmonaire ; l'équipe recherche d'abord une éventuelle détresse vitale.","src":"p. 156"},{"id":"230-case-02-s02","phase":1,"narrative":"À l'examen : PAS 108 mmHg, FC 104/min, pas de trouble de conscience, SpO2 à 94 %.","question":{"type":"QRU","stem":"Quel élément, s'il était présent, définirait chez Mme Dubreuil une embolie pulmonaire à haut risque ?","options":[{"t":"Une PAS < 90 mmHg, ou une chute de PAS > 40 mmHg pendant plus de 15 minutes","ok":true,"why":"C'est la définition retenue de l'hypotension définissant le haut risque."},{"t":"Une fréquence cardiaque supérieure à 100/min isolée","ok":false,"why":"La seule tachycardie ne définit pas le haut risque."},{"t":"Une SpO2 inférieure à 95 % isolée","ok":false,"why":"Ce seuil n'est pas celui retenu pour la stratification du risque de l'EP."},{"t":"Une douleur basithoracique de plus de 2 heures","ok":false,"why":"La durée de la douleur ne définit pas le haut risque dans l'EP."},{"t":"Une fièvre supérieure à 38,5 °C","ok":false,"why":"La fièvre n'est pas un critère de haut risque de l'EP."}],"explanation":"Le haut risque de l'EP est défini par une hypotension marquée ou prolongée, ou un état de choc."},"reveal":"La PAS de Mme Dubreuil reste supérieure à 90 mmHg et stable : il n'y a pas de choc. La démarche se poursuit hors situation de haut risque.","src":"p. 156"},{"id":"230-case-02-s03","phase":2,"narrative":"L'auscultation cardiopulmonaire est sans particularité, sans frottement péricardique ni asymétrie tensionnelle.","question":{"type":"QRM","stem":"Quels éléments plaident, chez cette patiente, en faveur d'une embolie pulmonaire plutôt que d'une autre des 4 urgences cardiovasculaires ?","options":[{"t":"La douleur est basithoracique, associée à une dyspnée","ok":true,"why":"C'est la présentation classique de l'embolie pulmonaire."},{"t":"La douleur est augmentée en décubitus et calmée par l'antéflexion du buste","ok":false,"why":"C'est la description typique de la péricardite, non de l'EP."},{"t":"L'absence de signes de thrombose veineuse n'élimine pas le diagnostic","ok":true,"why":"Des signes de thrombose veineuse sont absents dans un tiers des cas d'EP."},{"t":"Une asymétrie tensionnelle de plus de 20 mmHg entre les deux bras","ok":false,"why":"C'est un signe évocateur de dissection aortique."},{"t":"Un souffle d'insuffisance aortique","ok":false,"why":"C'est un signe évocateur de dissection aortique, non d'embolie pulmonaire."}],"explanation":"La présentation clinique de Mme Dubreuil (douleur basithoracique, dyspnée, absence de signes veineux non éliminatoire) est cohérente avec une embolie pulmonaire."},"reveal":"La radiographie thoracique est demandée en parallèle de l'ECG.","src":"p. 156"},{"id":"230-case-02-s04","phase":2,"narrative":"L'ECG est réalisé en urgence.","question":{"type":"QROC","question":"Quels signes ECG évocateurs de cœur pulmonaire aigu recherchez-vous chez Mme Dubreuil ?","answer":"Tachycardie sinusale, aspect S1Q3, bloc de branche droit, ondes T négatives en précordiales droites (V1-V3)","accept":["S1Q3","tachycardie sinusale, S1Q3, BBD, T négatives V1-V3"],"keywords":["S1Q3","tachycardie","bloc de branche droit","T négatives"],"explanation":"Ces signes traduisent la surcharge ventriculaire droite aiguë de l'embolie pulmonaire."},"reveal":"L'ECG montre une tachycardie sinusale et un aspect S1Q3, sans sus-décalage. La radiographie pulmonaire revient strictement normale.","src":"p. 156"},{"id":"230-case-02-s05","phase":3,"narrative":"En l'absence de choc, l'équipe doit estimer la probabilité clinique d'embolie pulmonaire avant de décider des examens complémentaires.","question":{"type":"QRU","stem":"Quel outil utilisez-vous pour estimer la probabilité clinique d'embolie pulmonaire chez Mme Dubreuil, en l'absence de choc ?","options":[{"t":"Le score de Wells modifié ou le score de Genève modifié","ok":true,"why":"Ce sont les scores cités pour estimer la probabilité clinique d'EP en l'absence de choc."},{"t":"Le score de probabilité clinique de dissection aortique","ok":false,"why":"Ce score est spécifique à la dissection aortique."},{"t":"Le score de probabilité clinique de coronaropathie chronique","ok":false,"why":"Ce score concerne les douleurs thoraciques chroniques d'origine coronarienne."},{"t":"Un dosage isolé de troponine","ok":false,"why":"La troponine a un intérêt pronostique dans l'EP, mais n'estime pas la probabilité clinique."},{"t":"La seule évaluation de la fréquence respiratoire","ok":false,"why":"Ce n'est pas un outil de stratification clinique validé dans ce chapitre."}],"explanation":"Le score de Wells modifié ou de Genève modifié est l'outil de référence cité pour la probabilité clinique d'EP en l'absence de choc."},"reveal":"Le score calculé situe la patiente à un niveau de probabilité intermédiaire.","src":"p. 156"},{"id":"230-case-02-s06","phase":3,"narrative":"La probabilité clinique est jugée intermédiaire. L'équipe décide de la conduite à tenir.","question":{"type":"QRM","stem":"Quelles décisions sont adaptées à ce niveau de probabilité clinique intermédiaire ?","options":[{"t":"Doser les D-dimères","ok":true,"why":"En probabilité faible ou modérée, les D-dimères doivent être prélevés."},{"t":"Débuter un traitement antithrombotique avant même la confirmation diagnostique","ok":true,"why":"En probabilité intermédiaire ou haute, le traitement est débuté avant la confirmation."},{"t":"Demander d'emblée un angioscanner sans doser les D-dimères","ok":false,"why":"Cette conduite est réservée à la probabilité clinique forte."},{"t":"Un taux de D-dimères négatif par méthode Elisa éliminerait le diagnostic","ok":true,"why":"Des D-dimères négatifs par méthode Elisa éliminent le diagnostic, même en probabilité prétest modérée."},{"t":"Différer toute décision thérapeutique jusqu'au résultat de l'angioscanner","ok":false,"why":"Le traitement antithrombotique doit être débuté avant la confirmation en cas de probabilité intermédiaire ou haute."}],"explanation":"En probabilité intermédiaire, les D-dimères guident la suite des explorations, mais le traitement antithrombotique est débuté sans attendre la confirmation diagnostique."},"reveal":"Le traitement antithrombotique est débuté. Les D-dimères sont prélevés en parallèle.","src":"p. 157"},{"id":"230-case-02-s07","phase":4,"narrative":"Le résultat des D-dimères revient à 720 µg/L.","question":{"type":"QROC","question":"Ce résultat étant positif, quel examen est alors demandé pour confirmer le diagnostic d'embolie pulmonaire ?","answer":"Un angioscanner thoracique","accept":["angioscanner pulmonaire","angio-TDM thoracique"],"keywords":["angioscanner","thoracique"],"explanation":"Des D-dimères positifs (> 500 µg/L chez cette patiente de moins de 50 ans) imposent un angioscanner thoracique pour confirmer le diagnostic."},"reveal":"L'angioscanner thoracique est programmé en urgence.","src":"p. 157"},{"id":"230-case-02-s08","phase":4,"narrative":"Avant le résultat de l'angioscanner, l'interne reprend les diagnostics différentiels envisageables devant ce tableau.","question":{"type":"QRM","stem":"Quels éléments, s'ils étaient présents chez Mme Dubreuil, orienteraient plutôt vers une péricardite aiguë que vers une embolie pulmonaire ?","options":[{"t":"Une douleur augmentée en décubitus et calmée par l'antéflexion du buste","ok":true,"why":"C'est la description typique de la douleur péricarditique."},{"t":"Un frottement péricardique à l'auscultation","ok":true,"why":"C'est un signe évocateur de péricardite, fugace et inconstant."},{"t":"Un contexte viral récent avec fièvre","ok":true,"why":"C'est le terrain classiquement évocateur de péricardite aiguë."},{"t":"Une chirurgie orthopédique récente avec alitement","ok":false,"why":"C'est au contraire un terrain évocateur d'embolie pulmonaire."},{"t":"Un aspect S1Q3 à l'ECG","ok":false,"why":"C'est un signe évocateur d'embolie pulmonaire, non de péricardite."}],"explanation":"Le contexte clinique et le caractère positionnel de la douleur permettent de différencier péricardite et embolie pulmonaire."},"reveal":"Aucun de ces éléments péricarditiques n'est retrouvé chez Mme Dubreuil, ce qui conforte l'hypothèse d'embolie pulmonaire en attendant l'imagerie.","src":"p. 156-157"},{"id":"230-case-02-s09","phase":5,"narrative":"L'angioscanner thoracique confirme une embolie pulmonaire segmentaire droite, sans signe de gravité. La patiente reste hémodynamiquement stable.","question":{"type":"QRM","stem":"Quelles affirmations sont exactes concernant la prise en charge de Mme Dubreuil à ce stade ?","options":[{"t":"Le traitement antithrombotique débuté avant la confirmation doit être poursuivi et adapté","ok":true,"why":"Le traitement précoce, justifié par la probabilité clinique, se poursuit une fois le diagnostic confirmé."},{"t":"L'absence de choc élimine toute nécessité de surveillance","ok":false,"why":"Une surveillance reste nécessaire même en l'absence de choc initial."},{"t":"La triade douleur basithoracique, dyspnée et radiographie normale est caractéristique de l'embolie pulmonaire","ok":true,"why":"Cette association doit faire évoquer obligatoirement le diagnostic."},{"t":"Le scanner thoracique n'était pas nécessaire puisque la patiente n'était pas à haut risque","ok":false,"why":"Le scanner reste l'examen de confirmation, quelle que soit la probabilité clinique en dehors du haut risque immédiat."},{"t":"Une réévaluation clinique régulière reste justifiée après confirmation","ok":true,"why":"La surveillance de l'évolution clinique reste de mise après le diagnostic."}],"explanation":"Le diagnostic confirmé, le traitement antithrombotique précoce est poursuivi et la patiente continue d'être surveillée."},"reveal":"Mme Dubreuil est hospitalisée quelques jours puis autorisée à rentrer à domicile sous traitement, avec un relais organisé en ambulatoire.","src":"p. 156-157"},{"id":"230-case-02-s10","phase":6,"narrative":"Lors de la consultation de sortie, l'interne doit expliquer la logique globale de la prise en charge suivie pour Mme Dubreuil.","question":{"type":"OPEN","prompt":"Résumez la démarche de stratification du risque de l'embolie pulmonaire, de l'admission jusqu'à la décision thérapeutique, telle qu'elle s'est appliquée à Mme Dubreuil.","rubric":[{"point":"Rechercher d'abord une hypotension ou un choc définissant le haut risque","weight":2},{"point":"En l'absence de choc, estimer la probabilité clinique par un score de Wells ou de Genève modifié","weight":2},{"point":"Doser les D-dimères si la probabilité est faible ou modérée ; angioscanner d'emblée si elle est forte","weight":2},{"point":"Débuter le traitement antithrombotique avant confirmation si la probabilité est intermédiaire ou haute","weight":2}],"model":"La démarche débute par la recherche d'une hypotension ou d'un choc, qui définirait un haut risque justifiant un scanner ou une échocardiographie en urgence. En l'absence de choc, la probabilité clinique est estimée par le score de Wells ou de Genève modifié : en probabilité faible ou modérée, les D-dimères orientent vers l'angioscanner s'ils sont positifs ; en probabilité forte, l'angioscanner est demandé d'emblée. Dès que la probabilité est intermédiaire ou haute, le traitement antithrombotique est débuté avant même la confirmation par l'imagerie."},"reveal":"L'interne valide sa synthèse avec le senior, qui insiste sur l'importance de ne pas retarder le traitement en cas de probabilité intermédiaire ou haute.","src":"p. 156-157"},{"id":"230-case-02-s11","phase":6,"narrative":"Pour clore le dossier, le senior interroge l'équipe sur la vision d'ensemble des urgences liées à une douleur thoracique aiguë.","question":{"type":"QRM","stem":"Concernant les urgences à évoquer devant une douleur thoracique aiguë, quelles affirmations sont exactes ?","options":[{"t":"Six urgences non cardiaques doivent être systématiquement identifiées en dehors des 4 urgences cardiovasculaires","ok":true,"why":"Pleurésie/pneumonie, pneumothorax, pancréatite aiguë, ulcère compliqué, cholécystite et douleur radiculaire en font partie."},{"t":"Un infarctus du myocarde inférieur peut mimer une gastro-entérite","ok":true,"why":"C'est un piège classique cité pour cette localisation d'infarctus."},{"t":"Une ischémie mésentérique peut compliquer une dissection aortique","ok":true,"why":"C'est une complication trompeuse à connaître, source de tableau abdominal égarant."},{"t":"Le diagnostic de douleur psychogène doit être posé en première intention devant toute douleur atypique","ok":false,"why":"C'est au contraire un diagnostic d'élimination, à poser avec prudence après avoir écarté les causes organiques."},{"t":"Une radiographie thoracique normale exclut toujours une cause organique","ok":false,"why":"Une radiographie normale est au contraire évocatrice d'embolie pulmonaire dans le contexte adapté."}],"explanation":"Au-delà des 4 urgences cardiovasculaires, il faut connaître les urgences non cardiaques et les pièges cliniques classiques du chapitre."},"reveal":"Le dossier de Mme Dubreuil est clos ; l'équipe retient l'importance d'une démarche rigoureuse associant terrain, clinique et examens complémentaires ciblés.","src":"p. 159-162"}]}],"ecg":{"data":[{"id":"230-ecg-01","title":"SCA avec sus-décalage persistant du ST (occlusion coronaire)","rank":"A","objective":"230-obj-07","ecg":{"rhythm":"sinus","rate":88,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.15,"avBlock":"none","qrs":{"dur":0.08,"bbb":"none","axis":30,"qWaves":[]},"st":{"elev":{"V2":3,"V3":4,"V4":3},"dep":{},"shape":"convex"},"t":{"inverted":[],"amp":0.3},"qt":0.38,"notes":"Sus-décalage convexe en regard du territoire occlus ; un ECG normal en pleine douleur n'élimine pas le diagnostic."},"findings":["Sus-décalage du segment ST convexe en regard du territoire ischémique","Absence d'onde Q à la phase aiguë","Rythme sinusal régulier","L'ECG conditionne la prise en charge et doit être réalisé sans délai"],"diagnosis":"Syndrome coronarien aigu avec sus-décalage persistant du segment ST","teaching":"Le sus-décalage persistant du ST impose un transfert médicalisé direct vers la coronarographie (ou l'USIC) sans attendre le dosage de la troponine, qui ne doit jamais retarder la reperfusion. Un bloc de branche gauche nouveau doit être considéré comme un équivalent de SCA ST+. Une ischémie de l'artère circonflexe peut être électriquement muette sur les dérivations standard : il faut savoir enregistrer V7, V8, V9, où un sus-décalage doit être traité comme un ST+ ; un sous-décalage isolé de V2 à V4 peut aussi la traduire.","quiz":{"stem":"Quelle est la conduite à tenir immédiate devant ce tracé chez un patient douloureux depuis 45 minutes ?","options":["Transfert médicalisé direct vers la coronarographie sans attendre la troponine","Attendre le résultat de la troponine ultrasensible avant toute décision","Réaliser d'abord une échocardiographie de repos","Débuter une surveillance simple en l'absence de douleur résiduelle"],"correct":0},"src":"p. 153-155"},{"id":"230-ecg-02","title":"SCA sans sus-décalage persistant du ST","rank":"A","objective":"230-obj-07","ecg":{"rhythm":"sinus","rate":92,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.15,"avBlock":"none","qrs":{"dur":0.08,"bbb":"none","axis":40,"qWaves":[]},"st":{"elev":{},"dep":{"V4":1.5,"V5":2,"V6":1.5},"shape":"horizontal"},"t":{"inverted":["V4","V5","V6"],"amp":0.2},"qt":0.38,"notes":"Sous-décalage horizontal et ondes T négatives ; la troponine, ici, apporte un intérêt diagnostique et pronostique majeur."},"findings":["Sous-décalage du segment ST de type horizontal en précordial","Ondes T négatives associées","Absence de sus-décalage persistant","L'ECG seul ne suffit pas : dosage de la troponine avec cinétique H0-H1/H2"],"diagnosis":"Syndrome coronarien aigu sans sus-décalage persistant du segment ST","teaching":"En l'absence de sus-décalage persistant, la troponine ultrasensible a un intérêt diagnostique et pronostique majeur : un dosage H0 très faible sans cinétique significative à H1-H2 oriente vers un diagnostic différentiel ou un SCA à bas risque surveillé en USIC, tandis qu'un dosage élevé ou une cinétique significative pose le diagnostic de SCA sans ST+ à haut risque.","quiz":{"stem":"Quel examen biologique apporte ici un intérêt diagnostique et pronostique majeur ?","options":["La troponine ultrasensible avec cinétique H0-H1/H2","Les D-dimères","La CRP seule","La créatine-kinase isolée"],"correct":0},"src":"p. 154-155"},{"id":"230-ecg-03","title":"Cœur pulmonaire aigu (embolie pulmonaire)","rank":"A","objective":"230-obj-07","ecg":{"rhythm":"sinusTachy","rate":118,"p":{"present":true,"amp":0.15,"dur":0.08,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.14,"avBlock":"none","qrs":{"dur":0.11,"bbb":"rbbb","axis":100,"qWaves":["III"]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["V1","V2","V3"],"amp":0.2},"qt":0.36,"notes":"Aspect S1Q3 : onde S profonde en dérivation I associée à l'onde Q en III modélisée ici ; bloc de branche droit et T négatives en précordial droit."},"findings":["Tachycardie sinusale","Aspect S1Q3","Bloc de branche droit","Ondes T négatives dans les précordiales droites (V1-V3)"],"diagnosis":"Signes électriques de cœur pulmonaire aigu (embolie pulmonaire)","teaching":"Ces anomalies traduisent une surcharge ventriculaire droite aiguë. L'association douleur thoracique, dyspnée et radiographie pulmonaire normale doit faire évoquer obligatoirement le diagnostic d'embolie pulmonaire. En cas d'hypotension (PAS < 90 mmHg ou chute > 40 mmHg pendant plus de 15 minutes) ou de choc, l'embolie pulmonaire est de haut risque et impose un scanner thoracique en urgence, ou à défaut une échocardiographie à la recherche d'une dilatation du ventricule droit.","quiz":{"stem":"Quel triple aspect électrique évoque un cœur pulmonaire aigu ?","options":["Tachycardie sinusale, aspect S1Q3, bloc de branche droit avec T négatives en précordial droit","Sus-décalage du ST concave diffus avec sous-décalage de PQ","Microvoltage avec alternance électrique","Bloc auriculo-ventriculaire de haut degré"],"correct":0},"src":"p. 156"},{"id":"230-ecg-04","title":"Péricardite aiguë non compliquée","rank":"A","objective":"230-obj-07","ecg":{"rhythm":"sinus","rate":90,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.15,"avBlock":"none","qrs":{"dur":0.08,"bbb":"none","axis":45,"qWaves":[]},"st":{"elev":{"I":1,"II":1.5,"III":1,"aVL":1,"aVF":1.5,"V2":1.5,"V3":2,"V4":2,"V5":1.5,"V6":1.5},"dep":{},"shape":"concave"},"t":{"inverted":[],"amp":0.3},"qt":0.38,"prDep":true,"notes":"Sus-décalage diffus, concave, non systématisé à un territoire coronaire, sans miroir ni onde Q ; sous-décalage du segment PQ associé."},"findings":["Sus-décalage du segment ST concave et diffus, non systématisé","Absence de miroir et d'onde Q","Sous-décalage du segment PQ","Parfois microvoltage associé"],"diagnosis":"Péricardite aiguë","teaching":"La péricardite aiguë est la plus bénigne des quatre urgences cardiovasculaires mais reste un diagnostic d'élimination. L'échocardiographie et la troponine sont systématiques ; l'échographie peut montrer un épanchement ou être normale (péricardite « sèche »), et il faut alors savoir la répéter.","quiz":{"stem":"Quelle caractéristique du sus-décalage du ST oriente vers une péricardite plutôt qu'un SCA ?","options":["Un aspect concave, diffus, sans miroir ni onde Q","Un aspect convexe systématisé à un territoire coronaire avec miroir","Un sous-décalage isolé en V1-V3","Un microvoltage isolé sans anomalie du ST"],"correct":0},"src":"p. 157"},{"id":"230-ecg-05","title":"Tamponnade péricardique","rank":"A","objective":"230-obj-07","ecg":{"rhythm":"sinusTachy","rate":110,"p":{"present":true,"amp":0.1,"dur":0.08,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.14,"avBlock":"none","qrs":{"dur":0.08,"bbb":"none","axis":45,"qWaves":[],"lowVoltage":true},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":[],"amp":0.15},"qt":0.36,"notes":"Microvoltage diffus ; une alternance électrique (variation d'amplitude du QRS d'un battement à l'autre, non modélisable ici) peut être observée."},"findings":["Microvoltage des complexes QRS","Tachycardie sinusale","Alternance électrique possible","Contexte de choc et de signes droits à l'examen"],"diagnosis":"Tamponnade péricardique","teaching":"La tamponnade est une urgence vitale, à l'inverse de la péricardite non compliquée. Elle associe des signes droits (turgescence jugulaire, reflux hépatojugulaire), un état de choc et un pouls paradoxal (chute de la PAS à l'inspiration > 10 mmHg par rapport à l'expiration). L'échocardiographie confirme le diagnostic : collapsus des cavités droites en expiration, compression du ventricule gauche par le ventricule droit en inspiration, épanchement abondant.","quiz":{"stem":"Quel signe électrique, associé à un contexte de choc et de signes droits, oriente vers une tamponnade ?","options":["Microvoltage, parfois avec alternance électrique","Sus-décalage convexe systématisé avec miroir","Aspect S1Q3 avec bloc de branche droit","Bloc auriculo-ventriculaire complet"],"correct":0},"src":"p. 157"}],"method":""},"echo":{"data":[{"id":"230-echo-01","title":"Tamponnade péricardique","rank":"A","objective":"230-obj-06","schematic":"a4c","findings":["Épanchement péricardique abondant","Collapsus des cavités droites en expiration","Compression du ventricule gauche par le ventricule droit en inspiration"],"measures":[],"description":"L'échocardiographie confirme le diagnostic de tamponnade devant un état de choc avec signes droits et pouls paradoxal. Trois signes sont attendus : le collapsus des cavités droites en expiration, la compression du ventricule gauche par le ventricule droit dilaté en inspiration, et un épanchement péricardique abondant. C'est un examen à réaliser en urgence devant tout tableau évocateur.","quiz":{"stem":"Quels signes échocardiographiques confirment une tamponnade péricardique ?","options":["Collapsus des cavités droites en expiration et compression du VG par le VD en inspiration, avec épanchement abondant","Dilatation isolée du ventricule droit sans épanchement","Trouble de la cinétique segmentaire du ventricule gauche","Épanchement péricardique minime sans retentissement"],"correct":0},"src":"p. 157"},{"id":"230-echo-02","title":"Cœur pulmonaire aigu (embolie pulmonaire à haut risque)","rank":"A","objective":"230-obj-06","schematic":"a4c","findings":["Dilatation du ventricule droit","Compression du ventricule gauche par le ventricule droit dilaté","Retentissement hémodynamique avec baisse de la pression artérielle systolique"],"measures":[],"description":"En cas d'embolie pulmonaire à haut risque, si le scanner thoracique n'est pas disponible immédiatement, l'échocardiographie est réalisée en urgence à la recherche d'une dilatation du ventricule droit, qui comprime le ventricule gauche et contribue à la baisse de la pression artérielle.","quiz":{"stem":"Quand l'échocardiographie est-elle indiquée en priorité dans l'embolie pulmonaire à haut risque ?","options":["Quand le scanner thoracique n'est pas disponible immédiatement","En première intention, avant tout scanner","Uniquement en l'absence de choc","Elle n'a aucune place dans l'EP à haut risque"],"correct":0},"src":"p. 156"},{"id":"230-echo-03","title":"Péricardite aiguë","rank":"A","objective":"230-obj-06","schematic":"plax","findings":["Épanchement péricardique possible mais inconstant","Échographie parfois normale (péricardite « sèche »)","Examen à répéter si la suspicion clinique persiste"],"measures":[],"description":"L'échocardiographie est systématique devant une suspicion de péricardite aiguë, avec le dosage de la troponine. Elle peut montrer un épanchement péricardique, ou être normale en cas de péricardite « sèche » : dans ce cas, il faut savoir la répéter si le tableau clinique reste évocateur.","quiz":{"stem":"Que faire si l'échocardiographie est normale malgré une forte suspicion clinique de péricardite ?","options":["Savoir la répéter, la péricardite pouvant être « sèche »","Éliminer d'emblée le diagnostic","Ne réaliser aucun autre examen","Conclure systématiquement à une tamponnade"],"correct":0},"src":"p. 157"},{"id":"230-echo-04","title":"Myopéricardite","rank":"B","objective":"230-obj-06","schematic":"a4c","findings":["Trouble de la cinétique du ventricule gauche, segmentaire ou diffus","Épanchement péricardique parfois associé","Fonction ventriculaire à réévaluer, un tableau d'insuffisance cardiaque pouvant s'associer"],"measures":[],"description":"La myopéricardite associe une atteinte myocardique à la péricardite, le plus souvent d'origine virale, avec une élévation prolongée de la troponine pouvant mimer un syndrome coronarien aigu. L'échocardiographie montre un trouble de la cinétique segmentaire ou diffus du ventricule gauche, avec un épanchement péricardique parfois associé ; la coronarographie, elle, est normale.","quiz":{"stem":"Quel examen invasif est normal dans la myopéricardite, à la différence d'un SCA ?","options":["La coronarographie","L'échocardiographie","La radiographie thoracique","L'ECG"],"correct":0},"src":"p. 158"}]}});
